// A human-friendly Deal ID in the format ##-###### (e.g. 21-123456). The first two digits
// are the current year (YY), the last six are random — used to match deals on import/export.
const newDealId = () => {
  const yy = String(new Date().getFullYear()).slice(-2)
  const n = Math.floor(100000 + Math.random() * 900000)
  return `${yy}-${n}`
}

// State that survives a page refresh by mirroring to localStorage.
// Per-user data namespace — every logged-in user gets their OWN saved data (keyed by email),
// so one account never sees or edits another account's data. Set on login, cleared on logout.
let DATA_NS = ''
export function setDataNamespace(ns) { DATA_NS = ns || '' }
const nsKey = (key) => (DATA_NS ? `${DATA_NS}::${key}` : key)

const readLS = (k, initial) => {
  try {
    const saved = localStorage.getItem(k)
    if (saved != null) return JSON.parse(saved)
  } catch { /* ignore */ }
  return initial
}

// Read a File as a data URL, and turn a stored data URL into a short-lived blob URL
// (browsers open blob: PDFs in a tab but block navigation to a large data: URL).
const readFileAsDataUrl = (f) =>
  new Promise((res, rej) => { const r = new FileReader(); r.onload = () => res(r.result); r.onerror = () => rej(r.error); r.readAsDataURL(f) })
// Public-package key derived from a property NAME, so a deal room's OM can feed the
// microsite "Download Package" for the listing with the same name.
const pkgNameKey = (name) => 'byname_' + String(name || '').toLowerCase().replace(/[^a-z0-9]/g, '')
const dataUrlToBlobUrl = (dataUrl) => {
  const [meta, b64] = String(dataUrl).split(',')
  const mime = (meta.match(/data:([^;]+)/) || [])[1] || 'application/octet-stream'
  const bin = atob(b64 || '')
  const arr = new Uint8Array(bin.length)
  for (let i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i)
  return URL.createObjectURL(new Blob([arr], { type: mime }))
}

function usePersistentState(key, initial) {
  const k = nsKey(key)
  const [state, setState] = useState(() => readLS(k, initial))
  // Which namespaced key the current in-memory state belongs to.
  const loadedKey = useRef(k)
  const cloudLoaded = useRef(false)
  // When the namespace changes (user logs in/out or switches accounts), the App
  // root does NOT remount — so we must reload THIS key's data and make sure the
  // previous account's in-memory state never gets written to the new account's key.
  if (loadedKey.current !== k) {
    loadedKey.current = k
    cloudLoaded.current = false
    setState(readLS(k, initial)) // re-init during render; React discards this render and re-runs
  }
  // Load this key's value from the cloud (so the WHOLE dashboard syncs across devices);
  // if the cloud has nothing yet, push up the local value (one-time migration).
  useEffect(() => {
    let alive = true
    cloudLoaded.current = false
    kvGet(key)
      .then((v) => {
        if (!alive) return
        if (v !== undefined) {
          setState(v)
          try { localStorage.setItem(k, JSON.stringify(v)) } catch { /* ignore */ }
        } else {
          kvSet(key, readLS(k, initial))
        }
        cloudLoaded.current = true
      })
      .catch(() => { cloudLoaded.current = true })
    return () => { alive = false }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [k])
  useEffect(() => {
    // Only persist once the state actually belongs to the current key.
    if (loadedKey.current === k) {
      try { localStorage.setItem(k, JSON.stringify(state)) } catch { /* ignore */ }
      if (cloudLoaded.current) kvSet(key, state) // mirror to the cloud once the initial load is done
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [k, state])
  return [state, setState]
}

// Relative "time ago" from a millisecond timestamp — updates as time passes.
const timeAgo = (ts) => {
  if (!ts) return ''
  const s = Math.max(0, Math.floor((Date.now() - ts) / 1000))
  if (s < 45) return 'just now'
  const m = Math.floor(s / 60)
  if (m < 60) return `${m} min${m === 1 ? '' : 's'} ago`
  const h = Math.floor(m / 60)
  if (h < 24) return `${h} hour${h === 1 ? '' : 's'} ago`
  const d = Math.floor(h / 24)
  if (d < 7) return `${d} day${d === 1 ? '' : 's'} ago`
  const w = Math.floor(d / 7)
  if (w < 5) return `${w} week${w === 1 ? '' : 's'} ago`
  const mo = Math.floor(d / 30)
  if (mo < 12) return `${mo} month${mo === 1 ? '' : 's'} ago`
  const y = Math.floor(d / 365)
  return `${y} year${y === 1 ? '' : 's'} ago`
}

/* --- Real action helpers (share / email / social / pdf) ------------------- */

const shareUrlFor = (item) =>
  `${window.location.origin}/p/${item.id}`

// Robust clipboard copy: Clipboard API first, legacy execCommand fallback.
const copyToClipboard = async (text) => {
  try {
    if (navigator.clipboard && window.isSecureContext) {
      await navigator.clipboard.writeText(text)
      return true
    }
  } catch {
    /* fall through to legacy path */
  }
  try {
    const ta = document.createElement('textarea')
    ta.value = text
    ta.style.position = 'fixed'
    ta.style.top = '-1000px'
    ta.style.opacity = '0'
    document.body.appendChild(ta)
    ta.focus()
    ta.select()
    const ok = document.execCommand('copy')
    document.body.removeChild(ta)
    return ok
  } catch {
    return false
  }
}

// Native share sheet where available, otherwise copy link to clipboard.
const shareItem = async (item, notify) => {
  const title = item.title || item.name
  const url = shareUrlFor(item)
  if (navigator.share) {
    try {
      await navigator.share({
        title: `Leadflow.io — ${title}`,
        text: `Check out ${title} — ${item.address}`,
        url,
      })
      notify('Shared successfully')
      return
    } catch (err) {
      if (err && err.name === 'AbortError') return // user closed the share sheet
      // otherwise fall back to copying the link
    }
  }
  const ok = await copyToClipboard(url)
  notify(ok ? 'Share link copied to clipboard' : 'Unable to copy link', ok ? 'success' : 'error')
}

