  const updCo = (id, k, v) => setForm((f) => ({ ...f, coAgents: f.coAgents.map((x) => (x.id === id ? { ...x, [k]: v } : x)) }))
  const delCo = (id) => setForm((f) => ({ ...f, coAgents: f.coAgents.filter((x) => x.id !== id) }))
