  const saveMap = (m) => { setForm((f) => ({ ...f, maps: f.maps.map((x) => (x.id === m.id ? m : x)) })); setMapEditor(null); notify('Map updated') }
  const delMap = (id) => setForm((f) => ({ ...f, maps: f.maps.filter((m) => m.id !== id) }))
  const [mapDel, setMapDel] = useState(null)
