/* -------------------------------------------------------------------------- */
/*  Deal form (create)                                                        */
/* -------------------------------------------------------------------------- */

function DealForm({ initialStage, onSubmit, onCancel }) {
  const [form, setForm] = useState({
    property: '',
    value: '',
    agent: '',
    stage: initialStage || 'Lead',
  })
  const set = (k) => (e) => setForm((f) => ({ ...f, [k]: e.target.value }))

  const submit = (e) => {
    e.preventDefault()
    if (!form.property.trim() || !form.agent.trim()) return
    const col = DEAL_COLUMNS.find((c) => c.key === form.stage)
    onSubmit({ ...form, value: Number(form.value) || 0, progress: col?.progress ?? 20 })
  }

  return (
    <form onSubmit={submit} className="space-y-4">
      <Field label="Property / Deal Name">
        <TextInput value={form.property} onChange={set('property')} placeholder="e.g. Cypress Corporate Tower" />
      </Field>
      <div className="grid grid-cols-2 gap-4">
        <Field label="Deal Value (USD)">
          <TextInput type="number" value={form.value} onChange={set('value')} placeholder="5000000" />
        </Field>
        <Field label="Assigned Agent">
          <TextInput value={form.agent} onChange={set('agent')} placeholder="Maya Chen" />
        </Field>
      </div>
      <Field label="Stage">
        <SelectInput value={form.stage} onChange={set('stage')} options={DEAL_COLUMNS.map((c) => c.key)} />
      </Field>
      <div className="flex justify-end gap-3 pt-2">
        <button
          type="button"
          onClick={onCancel}
          className="rounded-lg border border-slate-200 px-4 py-2 text-sm font-semibold text-slate-700 transition hover:bg-slate-50"
        >
          Cancel
        </button>
        <PrimaryButton type="submit">Create Deal</PrimaryButton>
      </div>
    </form>
  )
}

/* -------------------------------------------------------------------------- */
/*  Screen 3: Deal Rooms (Kanban with drag & drop)                           */
/* -------------------------------------------------------------------------- */

const DEAL_ROOM_STATUSES = ['Active', 'Archived']
const DEAL_ROOM_ACCESS = ['Free Access', 'Contact Required', 'NDA - Auto Access', 'NDA - Approval Required']

function DealRoomForm({ onSubmit, onCancel, initial, submitLabel = 'Create Deal Room' }) {
  const notify = useToast()
  const [form, setForm] = useState({ name: '', address: '', status: 'Active', access: 'Free Access', image: '', ...(initial || {}) })
  const [uploading, setUploading] = useState(false)
  const imgRef = useRef(null)
  const set = (k) => (e) => setForm((f) => ({ ...f, [k]: e.target.value }))
  const onImage = async (e) => {
    const file = e.target.files?.[0]
    e.target.value = ''
    if (!file) return
    if (!file.type.startsWith('image/')) { notify('Please choose an image file', 'error'); return }
    setUploading(true)
    try {
      // Read the image directly as a data URL — instant, works offline, and displays
      // everywhere (card, dashboard, detail) without any network/CORS dependency.
      const url = await new Promise((res, rej) => {
        const r = new FileReader()
        r.onload = () => res(r.result)
        r.onerror = () => rej(r.error)
        r.readAsDataURL(file)
      })
      setForm((f) => ({ ...f, image: url }))
    } catch {
      notify('Could not read that image — please try another', 'error')
    } finally {
      setUploading(false)
    }
  }
  const submit = (e) => {
    e.preventDefault()
    if (!form.name.trim()) return
    onSubmit(form)
  }
  return (
    <form onSubmit={submit} className="space-y-4">
      <Field label="Deal Room Name">
        <TextInput value={form.name} onChange={set('name')} placeholder="e.g. Riverside Business Park" />
      </Field>
      <Field label="Property Address">
        <TextInput value={form.address} onChange={set('address')} placeholder="123 Main St, City, State" />
      </Field>
      <div className="grid grid-cols-1 gap-4 sm:grid-cols-3">
        <Field label="Price">
          <TextInput value={form.price ?? ''} onChange={set('price')} placeholder="e.g. 4200000" />
        </Field>
        <Field label="CAP Rate (%)">
          <TextInput value={form.capRate ?? ''} onChange={set('capRate')} placeholder="e.g. 6.5" />
        </Field>
        <Field label="NOI">
          <TextInput value={form.noi ?? ''} onChange={set('noi')} placeholder="e.g. 273000" />
        </Field>
      </div>
      <Field label="Cover Image">
        <input ref={imgRef} type="file" accept="image/*" className="hidden" onChange={onImage} />
        {form.image ? (
          <div className="relative h-40 overflow-hidden rounded-lg border border-slate-200">
            <img src={form.image} alt="Cover" className="h-full w-full object-cover" />
            <div className="absolute right-2 top-2 flex gap-2">
              <button
                type="button"
                onClick={() => imgRef.current?.click()}
                className="rounded-lg bg-white/90 px-2.5 py-1 text-xs font-semibold text-slate-700 shadow-sm backdrop-blur transition hover:bg-white"
              >
                Change
              </button>
              <button
                type="button"
                onClick={() => setForm((f) => ({ ...f, image: '' }))}
                className="rounded-lg bg-white/90 px-2.5 py-1 text-xs font-semibold text-rose-600 shadow-sm backdrop-blur transition hover:bg-white"
              >
                Remove
              </button>
            </div>
          </div>
        ) : (
          <button
            type="button"
            onClick={() => imgRef.current?.click()}
            disabled={uploading}
            className="flex h-40 w-full flex-col items-center justify-center gap-2 rounded-lg border-2 border-dashed border-slate-200 bg-slate-50 text-slate-400 transition hover:border-slate-300 hover:text-slate-500 disabled:opacity-60"
          >
            {uploading ? (
              <span className="text-sm font-medium">Uploading…</span>
            ) : (
              <>
                <ImageIcon className="h-8 w-8" />
                <span className="text-sm font-medium">Click to upload an image</span>
                <span className="text-xs text-slate-400">PNG or JPG</span>
              </>
            )}
          </button>
        )}
      </Field>
      <div className="grid grid-cols-2 gap-4">
        <Field label="Status">
          <SelectInput value={form.status} onChange={set('status')} options={DEAL_ROOM_STATUSES} />
        </Field>
        <Field label="Access">
          <SelectInput value={form.access} onChange={set('access')} options={DEAL_ROOM_ACCESS} />
        </Field>
      </div>
      <div className="flex justify-end gap-3 pt-2">
        <button
          type="button"
          onClick={onCancel}
          className="rounded-lg border border-slate-200 px-4 py-2 text-sm font-semibold text-slate-700 transition hover:bg-slate-50"
        >
          Cancel
        </button>
        <PrimaryButton type="submit">{submitLabel}</PrimaryButton>
      </div>
    </form>
  )
}

function DealRoomCard({ room, onOpen, onDelete }) {
  const statusCls =
    room.status === 'Active'
      ? 'bg-emerald-500 text-white'
      : 'bg-slate-900/70 text-white backdrop-blur'
  return (
    <div
      onClick={onOpen}
      className="group cursor-pointer overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm transition hover:-translate-y-0.5 hover:shadow-md"
    >
      <div className="relative h-40 overflow-hidden bg-slate-100">
        {room.image ? (
          <img
            src={room.image}
            alt={room.name}
            onError={(e) => (e.currentTarget.src = FALLBACK_IMG)}
            className="h-full w-full object-cover transition duration-300 group-hover:scale-105"
            loading="lazy"
          />
        ) : (
          <div className="flex h-full w-full items-center justify-center bg-gradient-to-b from-slate-100 to-slate-200">
            <Building2 className="h-10 w-10 text-slate-300" />
          </div>
        )}
        <div className="absolute left-3 top-3 flex flex-wrap gap-2">
          <span className={`rounded-full px-2.5 py-1 text-xs font-semibold ${statusCls}`}>
            {room.status}
          </span>
          {room.access === 'Free Access' && (
            <span className="rounded-full bg-white/90 px-2.5 py-1 text-xs font-semibold text-slate-700 shadow-sm backdrop-blur">
              Free Access
            </span>
          )}
        </div>
        <button
          onClick={(e) => {
            e.stopPropagation()
            onDelete()
          }}
          className="absolute right-3 top-3 flex h-7 w-7 items-center justify-center rounded-lg bg-white/90 text-slate-400 opacity-0 shadow-sm backdrop-blur transition hover:text-rose-600 group-hover:opacity-100"
          title="Delete deal room"
        >
          <Trash2 className="h-4 w-4" />
        </button>
      </div>

      <div className="p-4">
        <h3 className="text-base font-bold text-slate-900">{room.name}</h3>
        <p className="mt-0.5 truncate text-sm text-slate-500">{room.address || '—'}</p>

        <div className="mt-3 flex items-center justify-between border-t border-slate-100 pt-3 text-sm text-slate-500">
          <div className="flex items-center gap-4">
            <span className="inline-flex items-center gap-1.5">
              <FileText className="h-4 w-4 text-slate-400" />
              {room.files}
            </span>
            <span className="inline-flex items-center gap-1.5">
              <Users className="h-4 w-4 text-slate-400" />
              {room.members}
            </span>
          </div>
          <span className="inline-flex items-center gap-1.5 text-slate-400">
            <Eye className="h-4 w-4" />
            {room.ts ? timeAgo(room.ts) : room.updated}
          </span>
        </div>
      </div>
    </div>
  )
}

