// Real OAuth endpoints. Clicking "Continue" opens the provider's genuine sign-in screen
// ONLY when a client ID is configured in .env.local — otherwise the demo connect runs.
const EMAIL_OAUTH = {
  gmail: {
    authorize: 'https://accounts.google.com/o/oauth2/v2/auth',
    clientId: import.meta.env.VITE_GOOGLE_OAUTH_CLIENT_ID,
    scope: 'https://www.googleapis.com/auth/gmail.send',
    extra: { access_type: 'offline', prompt: 'select_account', include_granted_scopes: 'true' },
  },
  outlook: {
    authorize: 'https://login.microsoftonline.com/common/oauth2/v2.0/authorize',
    clientId: import.meta.env.VITE_MS_OAUTH_CLIENT_ID,
    scope: 'https://graph.microsoft.com/Mail.Send offline_access',
    extra: { prompt: 'select_account' },
  },
  mailchimp: {
    authorize: 'https://login.mailchimp.com/oauth2/authorize',
    clientId: import.meta.env.VITE_MAILCHIMP_CLIENT_ID,
    scope: '',
    extra: {},
  },
  constant: {
    authorize: 'https://authz.constantcontact.com/oauth2/default/v1/authorize',
    clientId: import.meta.env.VITE_CONSTANT_CLIENT_ID,
    scope: 'contact_data campaign_data offline_access',
    extra: {},
  },
  // LinkedIn — same OAuth flow as Gmail. Needs a LinkedIn Developer App's Client ID in
  // VITE_LINKEDIN_CLIENT_ID. Scope is just sign-in for now (needs the "Sign In with LinkedIn
  // using OpenID Connect" product); add "w_member_social" back once "Share on LinkedIn" is
  // approved, to also enable posting.
  linkedin: {
    authorize: 'https://www.linkedin.com/oauth/v2/authorization',
    clientId: import.meta.env.VITE_LINKEDIN_CLIENT_ID,
    scope: 'openid profile email',
    // prompt=login forces LinkedIn to show its login screen every time, so the person signs in
    // with the account they choose instead of being auto-continued as whoever is already logged in.
    extra: { prompt: 'login' },
  },
  // Instagram — direct Instagram Business Login (Instagram's own login, no Facebook screen).
  // Uses the "Instagram app ID" from the app's Instagram business login setup in
  // VITE_INSTAGRAM_CLIENT_ID. The account must be Business/Creator and added as an Instagram
  // tester (accepted in Instagram) while the app is in development.
  instagram: {
    authorize: 'https://www.instagram.com/oauth/authorize',
    clientId: import.meta.env.VITE_INSTAGRAM_CLIENT_ID,
    scope: 'instagram_business_basic',
    // force_reauth makes Instagram always show its own login page, so each person signs in with
    // their own Instagram account instead of being auto-continued as whoever is already logged in.
    extra: { force_reauth: 'true' },
  },
}
// Opens the provider's sign-in in a NEW popup window (the dashboard tab never navigates away).
// Returns the popup window (caller watches it; the popup posts the code back and closes), or
// 'redirect' if pop-ups are blocked (same-tab fallback), or false if no client ID is configured.
function beginOAuth(providerKey) {
  const cfg = EMAIL_OAUTH[providerKey]
  if (!cfg || !cfg.clientId) return false
  // Instagram's business login registers the redirect WITH a trailing slash — match it exactly.
  const redirectUri = providerKey === 'instagram' ? window.location.origin + '/' : window.location.origin
  const base = { client_id: cfg.clientId, redirect_uri: redirectUri, response_type: 'code', state: providerKey, ...cfg.extra }
  if (cfg.scope) base.scope = cfg.scope
  const url = `${cfg.authorize}?${new URLSearchParams(base).toString()}`
  // Open in a NEW browser TAB (not a small popup window). The dashboard tab stays put; the new
  // tab posts the auth code back and closes itself when done.
  const w = window.open(url, '_blank')
  if (!w) { window.location.href = url; return 'redirect' } // pop-up blocked — fall back to same tab
  try { w.focus() } catch { /* ignore */ }
  return w
}

