function EmailBlastPage({ user, onNavigate, role = 'Member' }) {
  const canManageTemplates = ['Owner', 'Admin', 'Manager'].includes(role)
  const notify = useToast()
  const [conns, setConns] = usePersistentState('email_conns', {})
  const [campaigns, setCampaigns] = usePersistentState('email_campaigns', EMAIL_CAMPAIGNS_SEED)
  const [composeOpen, setComposeOpen] = useState(false)
  const [form, setForm] = useState({ audience: EMAIL_AUDIENCES[0], subject: '', body: '', type: 'individual', to: '' })
  const [sending, setSending] = useState(false)
  const [pickerOpen, setPickerOpen] = useState(false)
  const [templates, setTemplates] = usePersistentState('email_templates', EMAIL_TEMPLATES_SEED)
  const [tplEdit, setTplEdit] = useState(null) // template being edited (Manager+)
  const [liConnected, setLiConnected] = usePersistentState('email_linkedin', false)
  const [igConnected, setIgConnected] = usePersistentState('email_instagram', false)
  // The actual connected account per provider (name/email/username), resolved by the backend.
  const [socialAccounts, setSocialAccounts] = usePersistentState('email_social_accounts', {})
  // Finish a social connect: send the OAuth code to the backend, which returns the real account.
  const finishSocialConnect = async (provider, code) => {
    const redirectUri = provider === 'instagram' ? window.location.origin + '/' : window.location.origin
    try {
      const acct = await connectSocialAccount({ provider, code, redirectUri })
      setSocialAccounts((m) => ({ ...m, [provider]: acct }))
      if (provider === 'linkedin') setLiConnected(true)
      if (provider === 'instagram') setIgConnected(true)
      notify(`Connected ${acct.name || acct.email || provider}`, 'success')
    } catch (e) {
      notify(`Couldn't finish ${provider} connect — ${String(e.message || e)}`, 'error')
    }
  }
  const [liPost, setLiPost] = useState(null) // { listing, when } scheduling draft
  const [liScheduled, setLiScheduled] = usePersistentState('email_li_posts', [])
  const saveTpl = () => {
    if (!tplEdit.name.trim()) { notify('Template needs a name', 'error'); return }
    setTemplates((l) => l.map((t) => (t.id === tplEdit.id ? { ...tplEdit } : t)))
    setTplEdit(null)
    notify('Template saved for the whole team')
  }
  const useTemplate = (t) => { setForm({ audience: EMAIL_AUDIENCES[0], subject: t.subject, body: t.body, type: 'individual', to: '' }); setComposeOpen(true) }
  const scheduleLinkedIn = () => {
    if (!liPost.listing) { notify('Pick a listing', 'error'); return }
    setLiScheduled((l) => [{ id: uid(), listing: liPost.listing, when: liPost.when || 'ASAP', status: 'Scheduled' }, ...l])
    setLiPost(null)
    notify('LinkedIn post scheduled')
  }
  const [connectTarget, setConnectTarget] = useState(null)
  const [connecting, setConnecting] = useState(false)
  const [openingKey, setOpeningKey] = useState(null)
  const [tourStep, setTourStep] = useState(-1) // -1 = closed, 0..3 = step
  const [tourPos, setTourPos] = useState(null) // {top,left} when anchored below a target
  const tourCardRef = useRef(null)
  const [integrationsOpen, setIntegrationsOpen] = usePersistentState('email_integrations_open', false) // survives OAuth redirect / refresh
  const [connDates, setConnDates] = usePersistentState('email_conn_dates', {})
  const [sesFormOpen, setSesFormOpen] = useState(false)
  const [sesForm, setSesForm] = useState({ label: '', accessKeyId: '', secret: '', region: '', fromEmail: '', fromName: '' })
  const [sesConfig, setSesConfig] = usePersistentState('email_ses', null) // non-secret display info only
  const [signature, setSignature] = usePersistentState('email_signature', '') // SAVED signature (shown in preview)
  const [signatureLogo, setSignatureLogo] = usePersistentState('email_signature_logo', '')
  const [sigDraft, setSigDraft] = useState(signature) // live-editing draft; committed to saved on Save
  const [sigLogoDraft, setSigLogoDraft] = useState(signatureLogo)
  const [useSignature, setUseSignature] = usePersistentState('email_use_signature', false)
  const [socialConns, setSocialConns] = usePersistentState('email_social', {})
  const drafts = campaigns.filter((c) => c.status === 'Draft')
  const sent = campaigns.filter((c) => c.status === 'Sent')

  const setConnected = (p, on) => { setConns((c) => ({ ...c, [p.key]: on })); if (on) setConnDates((d) => ({ ...d, [p.key]: new Date().toLocaleDateString('en-GB') })) }
  const disconnect = (p) => { setConnected(p, false); notify(`Disconnected ${p.name}`, 'error') }
  const saveSes = () => {
    if (!sesForm.accessKeyId.trim() || !sesForm.secret.trim()) { notify('Enter your AWS Access Key ID and Secret', 'error'); return }
    setConns((c) => ({ ...c, ses: true }))
    setConnDates((d) => ({ ...d, ses: new Date().toLocaleDateString('en-GB') }))
    // Persist all fields (incl. keys) so they survive a page refresh / dev-server restart.
    // NOTE: keys are stored in this browser's localStorage — fine for local use, but do NOT
    // deploy/share this build with real keys entered, as localStorage is plain text.
    setSesConfig({ label: sesForm.label.trim() || 'Amazon SES', accessKeyId: sesForm.accessKeyId.trim(), secret: sesForm.secret.trim(), region: sesForm.region.trim(), fromEmail: sesForm.fromEmail.trim(), fromName: sesForm.fromName.trim() })
    notify('Amazon SES connected')
    setSesFormOpen(false)
    setSesForm({ label: '', accessKeyId: '', secret: '', region: '', fromEmail: '', fromName: '' })
  }
  const confirmConnect = () => {
    const p = connectTarget
    setConnecting(true)
    // If a real OAuth client ID is configured, redirect to the provider's genuine sign-in screen.
    if (beginOAuth(p.key)) return
    // Otherwise, authorize the demo connection.
    setTimeout(() => { setConnected(p, true); setConnecting(false); setConnectTarget(null); notify(`Connected ${p.name}`, 'success') }, 900)
  }
  // Connect directly (no confirm popup): show "Opening…" briefly, then open the provider in a
  // popup (dashboard never reloads) or connect. The message listener below finishes the connect.
  const startConnect = (p) => {
    if (openingKey === p.key) return // only block re-clicking the SAME one; others can still connect
    setOpeningKey(p.key)
    setTimeout(() => {
      const res = beginOAuth(p.key)
      if (res === 'redirect') return // full-page redirect fallback (navigates away)
      if (res) { // popup window opened — reset the button if the user closes it without authorizing
        const iv = setInterval(() => { if (res.closed) { clearInterval(iv); setOpeningKey((k) => (k === p.key ? null : k)) } }, 500)
        return
      }
      // No client ID configured → demo connect.
      setConnected(p, true)
      setOpeningKey(null)
      notify(`Connected ${p.name}`, 'success')
    }, 900)
  }
  // Anchor the tour card to the highlighted target (step 0 stays centered).
  useEffect(() => {
    if (tourStep <= 0) { setTourPos(null); return }
    const target = document.querySelector(`[data-tour-target="${tourStep}"]`)
    const card = tourCardRef.current
    if (!target) { setTourPos(null); return }
    // Bring the target into view so there's room for the card (instant = synchronous measure).
    target.scrollIntoView({ block: 'center', behavior: 'auto' })
    const r = target.getBoundingClientRect()
    const cardW = card?.offsetWidth || 448
    const cardH = card?.offsetHeight || 340
    const vw = window.innerWidth, vh = window.innerHeight
    let left = r.left + r.width / 2 - cardW / 2
    left = Math.max(12, Math.min(vw - cardW - 12, left))
    // Short targets (a button): sit fully below. Tall targets (a section): overlap the body,
    // keeping the section's label visible just above the card.
    const short = r.height < 160
    let top = short ? r.bottom + 12 : r.top + 56
    top = Math.max(12, Math.min(vh - cardH - 12, top))
    setTourPos({ top, left })
  }, [tourStep])
  // Handle the OAuth redirect back (?code=…&state=provider) — mark that provider connected.
  useEffect(() => {
    const q = new URLSearchParams(window.location.search)
    const code = q.get('code'), state = q.get('state')
    if (code && state && EMAIL_OAUTH[state]) {
      if (state === 'linkedin' || state === 'instagram') {
        // Resolve the real account on the backend (token exchange + profile).
        finishSocialConnect(state, code)
      } else {
        setConns((c) => ({ ...c, [state]: true }))
        setConnDates((d) => ({ ...d, [state]: new Date().toLocaleDateString('en-GB') }))
        notify(`Connected ${EMAIL_PROVIDERS.find((x) => x.key === state)?.name || state}`, 'success')
      }
      const url = new URL(window.location.href); url.searchParams.delete('code'); url.searchParams.delete('state'); url.searchParams.delete('scope'); window.history.replaceState({}, '', url.pathname + url.search)
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])
  // Finish a popup-based connect: the popup posts the code back here — no page reload.
  useEffect(() => {
    const onMsg = (e) => {
      if (e.origin !== window.location.origin) return
      const d = e.data
      if (d && d.type === 'oauth-connect' && d.state && EMAIL_OAUTH[d.state]) {
        setOpeningKey(null)
        if (d.state === 'linkedin' || d.state === 'instagram') {
          finishSocialConnect(d.state, d.code)
        } else {
          setConns((c) => ({ ...c, [d.state]: true }))
          setConnDates((dd) => ({ ...dd, [d.state]: new Date().toLocaleDateString('en-GB') }))
          notify(`Connected ${EMAIL_PROVIDERS.find((x) => x.key === d.state)?.name || d.state}`, 'success')
        }
      }
    }
    window.addEventListener('message', onMsg)
    return () => window.removeEventListener('message', onMsg)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])
  const startBlast = () => setPickerOpen(true)
  const chooseType = (type) => { setForm({ audience: EMAIL_AUDIENCES[0], subject: '', body: '', type, to: '' }); setPickerOpen(false); setComposeOpen(true) }
  const audienceCounts = { 'All Contacts': 842, 'Qualified Leads': 214, 'New Leads': 128, 'Active Deal Room Leads': 96 }
  const saveOrSend = async (asDraft) => {
    if (!form.subject.trim()) { notify('Add a subject first', 'error'); return }
    // Real send: if a recipient email is given, actually deliver it through the backend.
    if (!asDraft && form.to.trim()) {
      if (sending) return // guard against double-send
      setSending(true)
      try {
        const recipients = form.to.split(',').map((s) => s.trim()).filter(Boolean)
        await sendEmail({ to: recipients, subject: form.subject, body: (form.body || '').replace(/\n/g, '<br>'), fromName: user?.name })
        setCampaigns((list) => [{ id: uid(), name: form.subject, audience: recipients.join(', '), recipients: recipients.length, opens: 0, clicks: 0, status: 'Sent', date: 'just now' }, ...list])
        notify(`Email sent to ${recipients.length} recipient${recipients.length === 1 ? '' : 's'}`)
        setComposeOpen(false)
      } catch (e) {
        notify(`Send failed — ${String(e.message || e).includes('not configured') ? 'add Gmail App Password in server/.env' : 'check the recipient & try again'}`, 'error')
      } finally {
        setSending(false)
      }
      return
    }
    // No recipient (or saving a draft): keep the campaign record only.
    setCampaigns((list) => [{ id: uid(), name: form.subject, audience: form.audience, recipients: audienceCounts[form.audience], opens: 0, clicks: 0, status: asDraft ? 'Draft' : 'Sent', date: 'just now' }, ...list])
    notify(asDraft ? 'Draft saved automatically' : `Blast queued for ${form.audience}`)
    setComposeOpen(false)
  }
  const inputCls = 'w-full rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm text-slate-700 outline-none focus:border-orange-400'
  // When a tour step targets an element, lift it above the dim overlay with a white spotlight ring.
  const tourHi = (step) => (tourStep === step ? 'relative z-[46] rounded-2xl ring-4 ring-white' : '')

  return (
    <div className="mx-auto max-w-[1000px] p-6">
      {integrationsOpen ? (
      <div className="space-y-6">
        <button onClick={() => setIntegrationsOpen(false)} className="inline-flex items-center gap-1.5 text-sm font-semibold text-brand hover:underline"><ArrowLeft className="h-4 w-4" /> Distribution</button>
        <div>
          <h1 className="text-2xl font-extrabold text-slate-900">Integrations</h1>
          <p className="text-sm text-slate-500">Connect your email service to send marketing blasts, and your social accounts to post listings — all from any completed document.</p>
          <p className="mt-1 text-sm text-slate-500">On a direct SES send, recipients come straight from your <button onClick={() => onNavigate && onNavigate('crm')} className="font-semibold text-brand hover:underline">My Leads</button> — filter by tag, pipeline stage, or the buyers whose buy-box fits a listing (Mailchimp uses its own audience). New to this? Read the <span className="font-semibold text-brand">Distribution guide</span>.</p>
        </div>

        {/* Leadflow.io Mail (coming soon) */}
        <div className="rounded-xl border border-slate-200 bg-white p-5 shadow-sm">
          <div className="flex items-start gap-3">
            <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-lg bg-orange-50 text-brand"><Send className="h-5 w-5" /></span>
            <div className="min-w-0 flex-1">
              <p className="flex flex-wrap items-center gap-2 text-sm font-bold text-slate-900">Leadflow.io Mail — direct send <span className="rounded bg-slate-800 px-1.5 py-0.5 text-[10px] font-bold uppercase tracking-wide text-white">Coming soon</span></p>
              <p className="mt-0.5 text-sm text-slate-500">Send property emails straight from your own domain — no Mailchimp, Gmail, or AWS account to connect. You'll add three DNS records and your mail goes out as you. Until then, use one of the services below.</p>
            </div>
          </div>
        </div>

        {/* Email services */}
        <div>
          <p className="text-sm font-bold text-slate-900">Email services</p>
          <p className="text-xs text-slate-400">Or connect an account you already have. Most brokers use Mailchimp.</p>
          <div className="mt-3 grid gap-4 sm:grid-cols-2">
            {EMAIL_PROVIDERS.filter((p) => p.key !== 'download').map((p) => {
              const on = conns[p.key]
              const Icon = p.icon
              return (
                <div key={p.key} className={`flex flex-col rounded-xl border border-slate-200 bg-white p-4 shadow-sm ${p.key === 'ses' && sesFormOpen ? 'sm:col-span-2' : ''}`}>
                  <div className="flex items-start justify-between gap-3">
                    <div className="flex items-start gap-3">
                      <span className={`flex h-10 w-10 shrink-0 items-center justify-center rounded-lg ${p.tile}`}><Icon className="h-5 w-5" /></span>
                      <div><p className="text-sm font-bold text-slate-900">{p.name}{p.action === 'setup' && <span className="ml-1.5 text-xs font-normal text-slate-400">(Advanced)</span>}</p><p className="text-xs text-slate-400">{EMAIL_INTEGRATION_INFO[p.key]?.desc || p.sub}</p></div>
                    </div>
                    {on && <span className="shrink-0 rounded-full bg-emerald-50 px-2 py-0.5 text-xs font-semibold text-emerald-700">Connected</span>}
                  </div>
                  {EMAIL_INTEGRATION_INFO[p.key]?.note && !(p.key === 'ses' && sesFormOpen) && (
                    <p className="mt-3 rounded-lg bg-amber-50 px-3 py-2 text-xs leading-relaxed text-amber-800">{EMAIL_INTEGRATION_INFO[p.key].note}</p>
                  )}
                  <div className="mt-3">
                    {p.key === 'ses' ? (
                      sesFormOpen ? (
                        <>
                          <button onClick={() => setSesFormOpen(false)} className="rounded-full bg-orange-50 px-4 py-1.5 text-sm font-semibold text-brand transition hover:bg-orange-100">Cancel</button>
                          <div className="mt-4 space-y-3 border-t border-slate-100 pt-4">
                            <div><label className="mb-1 block text-xs font-semibold text-slate-500">Connection label</label><input value={sesForm.label} onChange={(e) => setSesForm((f) => ({ ...f, label: e.target.value }))} placeholder="My SES account" className={inputCls} /></div>
                            <div><label className="mb-1 block text-xs font-semibold text-slate-500">AWS Access Key ID</label><input value={sesForm.accessKeyId} onChange={(e) => setSesForm((f) => ({ ...f, accessKeyId: e.target.value }))} placeholder="AKIA…" className={inputCls} /></div>
                            <div><label className="mb-1 block text-xs font-semibold text-slate-500">AWS Secret Access Key</label><input type="password" value={sesForm.secret} onChange={(e) => setSesForm((f) => ({ ...f, secret: e.target.value }))} placeholder="••••••••••••••••" className={inputCls} /></div>
                            <div><label className="mb-1 block text-xs font-semibold text-slate-500">Region</label><input value={sesForm.region} onChange={(e) => setSesForm((f) => ({ ...f, region: e.target.value }))} placeholder="us-east-1" className={inputCls} /></div>
                            <div><label className="mb-1 block text-xs font-semibold text-slate-500">From email</label><input type="email" value={sesForm.fromEmail} onChange={(e) => setSesForm((f) => ({ ...f, fromEmail: e.target.value }))} placeholder="broker@example.com" className={inputCls} /></div>
                            <div><label className="mb-1 block text-xs font-semibold text-slate-500">From name</label><input value={sesForm.fromName} onChange={(e) => setSesForm((f) => ({ ...f, fromName: e.target.value }))} placeholder="Broker Name" className={inputCls} /></div>
                            <p className="text-xs text-slate-400">Make sure the From email is a verified identity in your SES account, or your SES is out of sandbox. Your keys are saved in this browser so they stay after a refresh — only use this on your own device, and don't deploy or share this build with real keys entered.</p>
                            <button onClick={saveSes} className="rounded-lg bg-brand px-4 py-2 text-sm font-bold text-white transition hover:bg-brand-hover">Save keys</button>
                          </div>
                        </>
                      ) : on ? (
                        <div>
                          <p className="text-xs text-slate-400">{sesConfig?.label || 'Amazon SES'} · connected {connDates.ses || new Date().toLocaleDateString('en-GB')}{sesConfig?.region ? ` · ${sesConfig.region}` : ''}</p>
                          <div className="mt-1.5 flex items-center gap-4 text-sm font-semibold"><button onClick={() => { setSesForm({ label: sesConfig?.label || '', accessKeyId: sesConfig?.accessKeyId || '', secret: sesConfig?.secret || '', region: sesConfig?.region || '', fromEmail: sesConfig?.fromEmail || '', fromName: sesConfig?.fromName || '' }); setSesFormOpen(true) }} className="text-brand hover:underline">Update</button><button onClick={() => { setConns((c) => ({ ...c, ses: false })); notify('Disconnected Amazon SES', 'error') }} className="text-slate-400 hover:text-rose-500">Disconnect</button></div>
                        </div>
                      ) : (
                        <button onClick={() => { setSesForm({ label: '', accessKeyId: '', secret: '', region: '', fromEmail: '', fromName: '' }); setSesFormOpen(true) }} className="rounded-full bg-orange-50 px-4 py-1.5 text-sm font-semibold text-brand transition hover:bg-orange-100">Connect Amazon SES</button>
                      )
                    ) : on ? (
                      <div>
                        <p className="text-xs text-slate-400">{p.name} · connected {connDates[p.key] || new Date().toLocaleDateString('en-GB')}</p>
                        <div className="mt-1.5 flex items-center gap-4 text-sm font-semibold"><button disabled={openingKey === p.key} onClick={() => startConnect(p)} className="text-brand hover:underline disabled:opacity-70">{openingKey === p.key ? 'Opening…' : 'Reconnect'}</button><button onClick={() => disconnect(p)} className="text-slate-400 hover:text-rose-500">Disconnect</button></div>
                      </div>
                    ) : (
                      <button disabled={openingKey === p.key} onClick={() => startConnect(p)} className="rounded-full bg-orange-50 px-4 py-1.5 text-sm font-semibold text-brand transition hover:bg-orange-100 disabled:opacity-70">{openingKey === p.key ? 'Opening…' : `Connect ${p.name}`}</button>
                    )}
                  </div>
                  {EMAIL_INTEGRATION_INFO[p.key]?.foot && !on && <p className="mt-2 text-xs text-slate-400">{EMAIL_INTEGRATION_INFO[p.key].foot}</p>}
                </div>
              )
            })}
          </div>
        </div>

        {/* Social accounts */}
        <div>
          <p className="text-sm font-bold text-slate-900">Social accounts</p>
          <p className="text-xs text-slate-400">Connect your own profiles to post listings directly from the Share to Social wizard.</p>
          <div className="mt-3 rounded-xl border border-slate-200 bg-white p-4 shadow-sm sm:max-w-sm">
            <div className="flex items-center gap-3">
              <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-lg bg-gradient-to-br from-pink-500 to-orange-400 text-white"><Instagram className="h-5 w-5" /></span>
              <div className="min-w-0 flex-1"><p className="text-sm font-bold text-slate-900">Instagram</p><p className="text-xs text-slate-400">Post a carousel or Story to your Instagram business account.</p></div>
            </div>
            <div className="mt-3">
              {socialConns.instagram ? (
                <div className="flex items-center gap-3 text-sm font-semibold"><span className="rounded-full bg-emerald-50 px-2 py-0.5 text-emerald-700">Connected</span><button onClick={() => { setSocialConns((s) => ({ ...s, instagram: false })); notify('Disconnected Instagram', 'error') }} className="text-slate-400 hover:text-rose-500">Disconnect</button></div>
              ) : (
                <button onClick={() => { setSocialConns((s) => ({ ...s, instagram: true })); notify('Connected Instagram') }} className="rounded-full bg-orange-50 px-4 py-1.5 text-sm font-semibold text-brand transition hover:bg-orange-100">Connect Instagram</button>
              )}
            </div>
          </div>
        </div>

        {/* Email signature */}
        <div className="rounded-xl border border-slate-200 bg-white p-5 shadow-sm">
          <div className="flex flex-wrap items-start justify-between gap-2">
            <div className="flex items-start gap-3">
              <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-orange-50 text-brand"><Pencil className="h-4 w-4" /></span>
              <div><p className="text-sm font-bold text-slate-900">Email signature</p><p className="max-w-xl text-sm text-slate-400">Added to the bottom of every email blast you send. Paste your signature straight out of Gmail or Outlook — common tables, logos and links are preserved.</p></div>
            </div>
            <label className="inline-flex items-center gap-1.5 text-sm text-slate-600"><input type="checkbox" checked={useSignature} onChange={(e) => setUseSignature(e.target.checked)} className="h-4 w-4 rounded border-slate-300 text-brand focus:ring-orange-400" /> Use it</label>
          </div>
          <label className="mt-4 block text-xs font-semibold text-slate-500">Signature</label>
          <textarea value={sigDraft} onChange={(e) => setSigDraft(e.target.value)} rows={4} placeholder="Your Name | Broker | leadflow.io | 555-000-0000" className="mt-1 w-full rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm outline-none focus:border-orange-400" />
          <label className="mt-3 block text-xs font-semibold text-slate-500">Logo URL (optional)</label>
          <input value={sigLogoDraft} onChange={(e) => setSigLogoDraft(e.target.value)} placeholder="https://.../logo.png" className="mt-1 w-full rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm outline-none focus:border-orange-400" />
          <p className="mt-1 text-xs text-slate-400">Must be a public http(s) image link — mail clients can't read an uploaded file.</p>
          <div className="mt-3 flex items-center gap-2">
            <button onClick={() => { setSignature(sigDraft); setSignatureLogo(sigLogoDraft); notify(sigDraft || sigLogoDraft ? 'Signature saved' : 'Signature cleared') }} className="rounded-lg bg-brand px-4 py-2 text-sm font-bold text-white transition hover:bg-brand-hover">Save signature</button>
            {(sigDraft || sigLogoDraft || signature || signatureLogo) && (
              <button onClick={() => { setSigDraft(''); setSigLogoDraft(''); setSignature(''); setSignatureLogo(''); setUseSignature(false); notify('Signature deleted', 'error') }} className="inline-flex items-center gap-1.5 rounded-lg border border-slate-200 px-4 py-2 text-sm font-semibold text-slate-600 transition hover:bg-rose-50 hover:text-rose-600"><Trash2 className="h-4 w-4" /> Delete</button>
            )}
          </div>
          {(signature || signatureLogo) && (
            <div className="mt-4 rounded-lg border border-slate-200 bg-slate-50/60">
              <p className="border-b border-slate-200 px-4 py-2 text-xs font-semibold text-slate-500">Preview — exactly what recipients will see</p>
              <div className="px-4 py-3">
                {signatureLogo && <img src={signatureLogo} alt="" className="mb-2 max-h-16 object-contain" onError={(e) => { e.currentTarget.style.display = 'none' }} />}
                <p className="whitespace-pre-line text-sm text-slate-700">{signature}</p>
              </div>
            </div>
          )}
        </div>
      </div>
      ) : (
      <>
      {/* Header */}
      <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
        <div>
          <h1 className="text-2xl font-extrabold text-slate-900">Distribution</h1>
          <p className="text-sm text-brand">Turn any completed property into a polished email — drafts save automatically as you work.</p>
        </div>
        <div className="flex items-center gap-2">
          <span data-tour-target="1" className={`inline-block ${tourHi(1)}`}><PrimaryButton icon={Plus} onClick={startBlast}>New email blast</PrimaryButton></span>
        </div>
      </div>

      {/* SEND WITH */}
      <div data-tour-target="2" className={`mt-7 ${tourHi(2)} ${tourStep === 2 ? 'bg-white p-4' : ''}`}>
      <div className="flex items-center justify-between">
        <p className="flex items-center gap-1.5 text-xs font-bold uppercase tracking-wide text-slate-500"><Send className="h-3.5 w-3.5" /> Send with</p>
        <button onClick={() => setIntegrationsOpen(true)} className="text-xs font-semibold text-brand hover:underline">Manage in Integrations →</button>
      </div>
      <div className="mt-3 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
        {EMAIL_PROVIDERS.map((p) => {
          const on = conns[p.key]
          const Icon = p.icon
          return (
            <div key={p.key} className="flex flex-col items-center rounded-xl border border-slate-200 bg-white p-4 text-center shadow-sm">
              <div className={`flex h-11 w-11 items-center justify-center rounded-xl ${p.tile}`}><Icon className="h-5 w-5" /></div>
              <p className="mt-2 text-sm font-bold text-slate-900">{p.name}</p>
              <p className="mt-0.5 text-xs text-slate-400">{p.sub}</p>
              <div className="mt-2.5">
                {p.action === 'ready' ? (
                  <span className="inline-flex items-center gap-1 text-sm font-semibold text-emerald-600"><CheckCircle2 className="h-4 w-4" /> Always ready</span>
                ) : p.action === 'setup' ? (
                  <button onClick={() => setIntegrationsOpen(true)} className="text-sm font-semibold text-brand hover:underline">Set up →</button>
                ) : on ? (
                  <div className="flex flex-col items-center gap-1">
                    <span className="inline-flex items-center gap-1 rounded-full bg-emerald-50 px-3 py-1 text-sm font-semibold text-emerald-700"><CheckCircle2 className="h-4 w-4" /> Connected</span>
                    <button onClick={() => disconnect(p)} className="text-xs font-medium text-slate-400 hover:text-rose-500">Disconnect</button>
                  </div>
                ) : (
                  <button disabled={openingKey === p.key} onClick={() => startConnect(p)} className="rounded-full bg-orange-50 px-4 py-1 text-sm font-semibold text-brand transition hover:bg-orange-100 disabled:opacity-70">{openingKey === p.key ? 'Opening…' : 'Connect'}</button>
                )}
              </div>
            </div>
          )
        })}
      </div>
      </div>

      {/* SEND WITH — Social (LinkedIn only, Milestone II 3.9) */}
      <div className="mt-7">
        <p className="flex items-center gap-1.5 text-xs font-bold uppercase tracking-wide text-slate-500"><Share2 className="h-3.5 w-3.5" /> Send with — Social</p>
        <div className="mt-3 rounded-xl border border-slate-200 bg-white p-4 shadow-sm">
          <div className="flex flex-wrap items-center justify-between gap-3">
            <div className="flex items-center gap-3">
              <span className="flex h-11 w-11 items-center justify-center rounded-xl bg-[#0A66C2] text-white"><Linkedin className="h-5 w-5" /></span>
              <div>
                <p className="text-sm font-bold text-slate-900">LinkedIn</p>
                <p className="text-xs text-slate-400">{liConnected && socialAccounts.linkedin ? `Connected as ${socialAccounts.linkedin.name || socialAccounts.linkedin.email}` : 'Post a listing to your feed. (Facebook & X come later.)'}</p>
              </div>
            </div>
            {liConnected ? (
              <div className="flex items-center gap-2">
                <button onClick={() => setLiPost({ listing: '', when: '' })} className="rounded-lg bg-brand px-3 py-1.5 text-sm font-bold text-white transition hover:bg-brand-hover">Schedule post</button>
                <button onClick={() => { setLiConnected(false); notify('Disconnected LinkedIn', 'error') }} className="text-xs font-medium text-slate-400 hover:text-rose-500">Disconnect</button>
              </div>
            ) : (
              <button onClick={() => { const r = beginOAuth('linkedin'); if (r === false) notify('LinkedIn isn\'t set up yet — add your LinkedIn app Client ID (VITE_LINKEDIN_CLIENT_ID) to enable Connect', 'error') }} className="rounded-full bg-orange-50 px-4 py-1.5 text-sm font-semibold text-brand transition hover:bg-orange-100">Connect</button>
            )}
          </div>
          {/* Instagram — connects via Facebook (Meta). Needs a Business IG account + Facebook Page. */}
          <div className="mt-3 flex flex-wrap items-center justify-between gap-3 border-t border-slate-100 pt-3">
            <div className="flex items-center gap-3">
              <span className="flex h-11 w-11 items-center justify-center rounded-xl bg-gradient-to-tr from-[#F58529] via-[#DD2A7B] to-[#8134AF] text-white"><Instagram className="h-5 w-5" /></span>
              <div>
                <p className="text-sm font-bold text-slate-900">Instagram</p>
                <p className="text-xs text-slate-400">{igConnected && socialAccounts.instagram ? `Connected as ${socialAccounts.instagram.name || socialAccounts.instagram.username}` : 'Post a listing to your feed. (Business/Creator account required.)'}</p>
              </div>
            </div>
            {igConnected ? (
              <button onClick={() => { setIgConnected(false); notify('Disconnected Instagram', 'error') }} className="text-xs font-medium text-slate-400 hover:text-rose-500">Disconnect</button>
            ) : (
              <button onClick={() => { const r = beginOAuth('instagram'); if (r === false) notify('Instagram isn\'t set up yet — add your Facebook app ID (VITE_INSTAGRAM_CLIENT_ID) to enable Connect', 'error') }} className="rounded-full bg-orange-50 px-4 py-1.5 text-sm font-semibold text-brand transition hover:bg-orange-100">Connect</button>
            )}
          </div>
          {liScheduled.length > 0 && (
            <div className="mt-3 space-y-1.5 border-t border-slate-100 pt-3">
              {liScheduled.map((s) => (
                <div key={s.id} className="flex items-center justify-between text-sm">
                  <span className="text-slate-700"><Linkedin className="mr-1.5 inline h-3.5 w-3.5 text-[#0A66C2]" />{s.listing}</span>
                  <span className="flex items-center gap-2 text-xs text-slate-400">{s.when} · <span className="rounded-full bg-blue-50 px-2 py-0.5 font-semibold text-blue-700">{s.status}</span>
                    <button onClick={() => { setLiScheduled((l) => l.filter((x) => x.id !== s.id)); notify('Post removed', 'error') }} className="text-slate-300 hover:text-rose-500"><Trash2 className="h-3.5 w-3.5" /></button>
                  </span>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* CAMPAIGN TEMPLATES — Just Listed / Price Reduced / Sold (Manager-controlled) */}
      <div className="mt-8">
        <div className="flex items-center justify-between">
          <p className="flex items-center gap-1.5 text-xs font-bold uppercase tracking-wide text-slate-500"><LayoutTemplate className="h-3.5 w-3.5" /> Campaign templates</p>
          <span className="text-xs text-slate-400">{canManageTemplates ? 'You can edit these' : 'Manager-controlled'}</span>
        </div>
        <div className="mt-3 grid gap-3 sm:grid-cols-3">
          {templates.map((t) => (
            <div key={t.id} className="flex flex-col rounded-xl border border-slate-200 bg-white p-4 shadow-sm">
              <p className="text-sm font-bold text-slate-900">{t.name}</p>
              <p className="mt-1 line-clamp-2 text-xs text-slate-500">{t.subject}</p>
              <div className="mt-3 flex items-center gap-3 text-sm font-semibold">
                <button onClick={() => useTemplate(t)} className="text-brand hover:underline">Use</button>
                {canManageTemplates && <button onClick={() => setTplEdit({ ...t })} className="text-slate-500 hover:underline">Edit</button>}
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* LinkedIn schedule modal */}
      {liPost && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 p-4">
          <div className="w-full max-w-md rounded-2xl bg-white p-6 shadow-xl">
            <div className="flex items-center justify-between"><p className="text-lg font-bold text-slate-900">Schedule LinkedIn post</p><button onClick={() => setLiPost(null)} className="text-slate-400 hover:text-slate-700"><X className="h-5 w-5" /></button></div>
            <div className="mt-4 space-y-3">
              <div><label className="mb-1 block text-xs font-semibold text-slate-500">Listing</label><select value={liPost.listing} onChange={(e) => setLiPost((p) => ({ ...p, listing: e.target.value }))} className={inputCls}><option value="">— Pick a listing —</option>{INITIAL_LISTINGS.map((l) => <option key={l.id} value={l.name}>{l.name}</option>)}</select></div>
              <div><label className="mb-1 block text-xs font-semibold text-slate-500">When</label><input type="datetime-local" value={liPost.when} onChange={(e) => setLiPost((p) => ({ ...p, when: e.target.value }))} className={inputCls} /></div>
            </div>
            <div className="mt-5 flex justify-end gap-2"><button onClick={() => setLiPost(null)} className="rounded-lg border border-slate-200 px-4 py-2 text-sm font-semibold text-slate-700 hover:bg-slate-50">Cancel</button><button onClick={scheduleLinkedIn} className="rounded-lg bg-brand px-4 py-2 text-sm font-bold text-white hover:bg-brand-hover">Schedule</button></div>
          </div>
        </div>
      )}

      {/* Template edit modal (Manager+) */}
      {tplEdit && (
        <div className="fixed inset-0 z-50 flex items-start justify-center overflow-y-auto bg-slate-900/40 p-4">
          <div className="my-8 w-full max-w-lg rounded-2xl bg-white p-6 shadow-xl">
            <div className="flex items-center justify-between"><p className="text-lg font-bold text-slate-900">Edit template</p><button onClick={() => setTplEdit(null)} className="text-slate-400 hover:text-slate-700"><X className="h-5 w-5" /></button></div>
            <div className="mt-4 space-y-3">
              <div><label className="mb-1 block text-xs font-semibold text-slate-500">Name</label><input value={tplEdit.name} onChange={(e) => setTplEdit((t) => ({ ...t, name: e.target.value }))} className={inputCls} /></div>
              <div><label className="mb-1 block text-xs font-semibold text-slate-500">Subject</label><input value={tplEdit.subject} onChange={(e) => setTplEdit((t) => ({ ...t, subject: e.target.value }))} className={inputCls} /></div>
              <div><label className="mb-1 block text-xs font-semibold text-slate-500">Body</label><textarea rows={8} value={tplEdit.body} onChange={(e) => setTplEdit((t) => ({ ...t, body: e.target.value }))} className={`${inputCls} resize-y`} /></div>
              <p className="text-xs text-slate-400">Merge fields like {'{{property}}, {{price}}, {{link}}'} are filled per listing.</p>
            </div>
            <div className="mt-5 flex justify-end gap-2"><button onClick={() => setTplEdit(null)} className="rounded-lg border border-slate-200 px-4 py-2 text-sm font-semibold text-slate-700 hover:bg-slate-50">Cancel</button><button onClick={saveTpl} className="rounded-lg bg-brand px-4 py-2 text-sm font-bold text-white hover:bg-brand-hover">Save for the team</button></div>
          </div>
        </div>
      )}

      {/* DRAFTS */}
      <div data-tour-target="3" className={`mt-8 ${tourHi(3)} ${tourStep === 3 ? 'bg-white p-4' : ''}`}>
      <p className="flex items-center gap-1.5 text-xs font-bold uppercase tracking-wide text-slate-500"><FileText className="h-3.5 w-3.5" /> Drafts</p>
      {drafts.length === 0 ? (
        <div className="mt-3 flex flex-col items-center justify-center rounded-xl border-2 border-dashed border-slate-200 py-10 text-center">
          <span className="flex h-9 w-9 items-center justify-center rounded-full border border-slate-300 text-slate-400"><Plus className="h-5 w-5" /></span>
          <p className="mt-3 text-sm font-bold text-slate-700">No drafts yet</p>
          <p className="mt-1 text-sm text-slate-500">Start one and it saves automatically — leave and come back any time.</p>
          <button onClick={startBlast} className="mt-4 rounded-lg bg-brand px-4 py-2 text-sm font-bold text-white transition hover:bg-brand-hover">Create your first email blast</button>
        </div>
      ) : (
        <div className="mt-3 space-y-2">
          {drafts.map((c) => (
            <div key={c.id} className="flex items-center justify-between rounded-xl border border-slate-200 bg-white p-4 shadow-sm">
              <div className="flex items-center gap-3"><span className="flex h-9 w-9 items-center justify-center rounded-lg bg-slate-100 text-slate-400"><FileText className="h-4 w-4" /></span><div><p className="text-sm font-bold text-slate-800">{c.name}</p><p className="text-xs text-slate-400">{c.audience} · {c.recipients.toLocaleString()} recipients · saved {c.date}</p></div></div>
              <div className="flex items-center gap-2">
                <button onClick={() => { setForm({ audience: c.audience, subject: c.name, body: '' }); setComposeOpen(true) }} className="rounded-lg border border-slate-200 px-3 py-1.5 text-sm font-semibold text-slate-700 transition hover:bg-slate-50">Edit</button>
                <button onClick={() => { setCampaigns((l) => l.map((x) => x.id === c.id ? { ...x, status: 'Sent', date: 'just now' } : x)); notify(`Blast sent to ${c.audience}`) }} className="rounded-lg bg-brand px-3 py-1.5 text-sm font-semibold text-white transition hover:bg-brand-hover">Send</button>
                <button onClick={() => setCampaigns((l) => l.filter((x) => x.id !== c.id))} className="rounded p-1.5 text-slate-400 transition hover:bg-rose-50 hover:text-rose-500"><Trash2 className="h-4 w-4" /></button>
              </div>
            </div>
          ))}
        </div>
      )}
      </div>

      {/* SENT */}
      <p className="mt-8 flex items-center gap-1.5 text-xs font-bold uppercase tracking-wide text-slate-500"><Send className="h-3.5 w-3.5" /> Sent</p>
      {sent.length === 0 ? (
        <div className="mt-3 rounded-xl border-2 border-dashed border-slate-200 py-8 text-center text-sm text-slate-500">Nothing sent yet — your send history and provider links will show up here.</div>
      ) : (
        <div className="mt-3 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
          <div className="scrollbar-slim overflow-x-auto">
            <table className="w-full min-w-[640px] text-left text-sm">
              <thead><tr className="border-b border-slate-200 bg-slate-50 text-xs font-semibold uppercase tracking-wide text-slate-400"><th className="px-4 py-2.5">Campaign</th><th className="px-4 py-2.5">Audience</th><th className="px-4 py-2.5 text-right">Recipients</th><th className="px-4 py-2.5 text-right">Opens</th><th className="px-4 py-2.5 text-right">Clicks</th><th className="px-4 py-2.5 text-right">Sent</th></tr></thead>
              <tbody>
                {sent.map((c) => (
                  <tr key={c.id} className="border-b border-slate-100 last:border-0 hover:bg-slate-50">
                    <td className="px-4 py-2.5 font-semibold text-slate-800">{c.name}</td>
                    <td className="px-4 py-2.5 text-slate-500">{c.audience}</td>
                    <td className="px-4 py-2.5 text-right text-slate-600">{c.recipients.toLocaleString()}</td>
                    <td className="px-4 py-2.5 text-right text-slate-600">{c.opens}</td>
                    <td className="px-4 py-2.5 text-right text-slate-600">{c.clicks}</td>
                    <td className="px-4 py-2.5 text-right text-slate-400">{c.date}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
      </>
      )}

      {/* Guided tour */}
      {tourStep >= 0 && (() => {
        const s = EMAIL_TOUR[tourStep]
        const Icon = s.icon
        const last = tourStep === EMAIL_TOUR.length - 1
        const anchored = tourPos && tourStep > 0
        return (
          <>
          <div className="fixed inset-0 z-40 bg-black/50" onClick={() => setTourStep(-1)} />
          <div className={`pointer-events-none fixed inset-0 z-50 ${anchored ? '' : 'flex items-center justify-center p-4'}`}>
            <div
              key={tourStep}
              ref={tourCardRef}
              style={anchored ? { top: tourPos.top, left: tourPos.left } : {}}
              className={`tour-step-in pointer-events-auto w-[448px] max-w-[calc(100vw-2rem)] rounded-2xl bg-white p-6 shadow-2xl ${anchored ? 'fixed' : ''}`}
              onClick={(e) => e.stopPropagation()}
            >
              <div className="flex items-start justify-between">
                <span className={`flex h-11 w-11 items-center justify-center rounded-xl ${s.tile}`}><Icon className="h-6 w-6" /></span>
                <button onClick={() => setTourStep(-1)} className="text-slate-400 hover:text-slate-700"><X className="h-5 w-5" /></button>
              </div>
              <p className="mt-4 text-lg font-bold text-slate-900">{s.title}</p>
              <p className="mt-2 text-sm leading-relaxed text-slate-500">{s.body}</p>
              <div className="mt-5 flex items-center justify-between">
                <div className="flex items-center gap-1.5">
                  {EMAIL_TOUR.map((_, i) => <span key={i} className={`h-1.5 rounded-full transition-all ${i === tourStep ? 'w-5 bg-brand' : 'w-1.5 bg-slate-200'}`} />)}
                </div>
                <div className="flex items-center gap-3">
                  {tourStep === 0 ? (
                    <button onClick={() => setTourStep(-1)} className="text-sm font-semibold text-slate-500 hover:text-slate-800">Skip</button>
                  ) : (
                    <button onClick={() => setTourStep((n) => n - 1)} className="inline-flex items-center gap-1 text-sm font-semibold text-slate-500 hover:text-slate-800"><ArrowLeft className="h-4 w-4" /> Back</button>
                  )}
                  <button onClick={() => (last ? setTourStep(-1) : setTourStep((n) => n + 1))} className="inline-flex items-center gap-1.5 rounded-lg bg-brand px-4 py-2 text-sm font-bold text-white transition hover:bg-brand-hover">
                    {tourStep === 0 ? 'Show me' : last ? 'Done' : 'Next'} {!last && <ArrowRight className="h-4 w-4" />}
                  </button>
                </div>
              </div>
              <p className="mt-3 text-right text-xs text-slate-400">{tourStep + 1} of {EMAIL_TOUR.length}</p>
            </div>
          </div>
          </>
        )
      })()}

      {/* Connect / authorize modal */}
      {connectTarget && (() => {
        const p = connectTarget
        const Icon = p.icon
        return (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4" onClick={() => !connecting && setConnectTarget(null)}>
            <div className="w-full max-w-md rounded-2xl bg-white p-6 text-center shadow-2xl" onClick={(e) => e.stopPropagation()}>
              <span className={`mx-auto flex h-14 w-14 items-center justify-center rounded-xl ${p.tile}`}><Icon className="h-7 w-7" /></span>
              <p className="mt-4 text-lg font-bold text-slate-900">Connect {p.name}</p>
              <p className="mt-2 text-sm text-slate-500">You'll be securely redirected to {p.name} to sign in and authorize Leadflow.io to send on your behalf. We never see your password.</p>
              <div className="mt-5 flex justify-center gap-2">
                <button disabled={connecting} onClick={() => setConnectTarget(null)} className="rounded-lg border border-slate-300 px-4 py-2 text-sm font-semibold text-slate-700 transition hover:bg-slate-50 disabled:opacity-50">Cancel</button>
                <button disabled={connecting} onClick={confirmConnect} className="inline-flex items-center gap-2 rounded-lg bg-brand px-5 py-2 text-sm font-bold text-white transition hover:bg-brand-hover disabled:opacity-70">
                  {connecting ? <><Loader2 className="h-4 w-4 animate-spin" /> Connecting…</> : <>Continue to {p.name}</>}
                </button>
              </div>
              <p className="mt-3 text-xs text-slate-400">Leadflow.io only requests permission to send emails — nothing else.</p>
            </div>
          </div>
        )
      })()}

      {/* Kind picker modal */}
      {pickerOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4" onClick={() => setPickerOpen(false)}>
          <div className="w-full max-w-2xl rounded-2xl bg-white shadow-2xl" onClick={(e) => e.stopPropagation()}>
            <div className="flex items-center justify-between border-b border-slate-100 px-6 py-4">
              <p className="text-lg font-bold text-slate-900">New email blast</p>
              <button onClick={() => setPickerOpen(false)} className="text-slate-400 hover:text-slate-700"><X className="h-5 w-5" /></button>
            </div>
            <div className="px-6 py-5">
              <p className="text-sm text-slate-500">What kind of email do you want to create?</p>
              <div className="mt-4 grid gap-4 sm:grid-cols-2">
                {[
                  { type: 'individual', icon: Building2, title: 'Individual property', desc: 'Feature a single listing with your choice of template, colors & sections' },
                  { type: 'multi', icon: BuildingsIcon, title: 'Multi-property', desc: 'Feature several listings together in one portfolio email' },
                ].map((o) => (
                  <div key={o.type} className="flex flex-col items-center rounded-xl border border-slate-200 p-6 text-center transition hover:border-orange-300 hover:shadow-sm">
                    <span className="flex h-14 w-14 items-center justify-center rounded-full bg-orange-50 text-brand"><o.icon className="h-7 w-7" /></span>
                    <p className="mt-3 text-base font-bold text-slate-900">{o.title}</p>
                    <p className="mt-1 text-sm text-slate-500">{o.desc}</p>
                    <button onClick={() => chooseType(o.type)} className="mt-4 rounded-lg bg-brand px-5 py-2 text-sm font-bold text-white transition hover:bg-brand-hover">Create</button>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Compose modal */}
      {composeOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4" onClick={() => setComposeOpen(false)}>
          <div className="w-full max-w-xl rounded-2xl bg-white p-6 shadow-2xl" onClick={(e) => e.stopPropagation()}>
            <div className="flex items-center justify-between"><p className="text-base font-bold text-slate-900">New email blast <span className="font-normal text-slate-400">· {form.type === 'multi' ? 'Multi-property' : 'Individual property'}</span></p><button onClick={() => setComposeOpen(false)} className="text-slate-400 hover:text-slate-700"><X className="h-5 w-5" /></button></div>
            <div className="mt-4"><label className="mb-1 block text-xs font-semibold text-slate-500">Audience</label><select value={form.audience} onChange={(e) => setForm((f) => ({ ...f, audience: e.target.value }))} className={inputCls}>{EMAIL_AUDIENCES.map((a) => <option key={a}>{a} ({audienceCounts[a].toLocaleString()})</option>)}</select></div>
            <div className="mt-3"><label className="mb-1 block text-xs font-semibold text-slate-500">To <span className="font-normal text-slate-400">(recipient email — sends a real email; comma-separate for many)</span></label><input value={form.to} onChange={(e) => setForm((f) => ({ ...f, to: e.target.value }))} placeholder="buyer@example.com, agent@example.com" className={inputCls} /></div>
            <div className="mt-3"><label className="mb-1 block text-xs font-semibold text-slate-500">Subject</label><input value={form.subject} onChange={(e) => setForm((f) => ({ ...f, subject: e.target.value }))} placeholder="e.g. New Off-Market Retail Opportunity" className={inputCls} /></div>
            <div className="mt-3"><label className="mb-1 block text-xs font-semibold text-slate-500">Message</label><textarea value={form.body} onChange={(e) => setForm((f) => ({ ...f, body: e.target.value }))} rows={6} placeholder="Write your email…" className={`${inputCls} resize-y`} /></div>
            <div className="mt-4 flex items-center justify-between gap-2">
              <p className="text-xs text-slate-400">{form.type === 'multi' ? 'Multi-property sending is coming soon — save it as a draft for now.' : ''}</p>
              <div className="flex gap-2">
                <button onClick={() => saveOrSend(true)} className="rounded-lg border border-slate-300 px-4 py-2 text-sm font-semibold text-slate-700 transition hover:bg-slate-50">Save draft</button>
                <button disabled={form.type === 'multi' || sending} onClick={() => saveOrSend(false)} title={form.type === 'multi' ? 'Coming soon for multi-property' : ''} className={`inline-flex items-center gap-1.5 rounded-lg px-4 py-2 text-sm font-bold text-white transition ${form.type === 'multi' || sending ? 'cursor-not-allowed bg-orange-300' : 'bg-brand hover:bg-brand-hover'}`}><Send className="h-4 w-4" /> {sending ? 'Sending…' : form.to.trim() ? 'Send email' : 'Send blast'}</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

/* -------------------------------------------------------------------------- */
/*  Profile Settings & Team Settings                                           */
/* -------------------------------------------------------------------------- */

function SettingsField({ label, value, onChange, type = 'text', placeholder }) {
  return (
    <div>
      <label className="mb-1 block text-xs font-semibold text-slate-500">{label}</label>
      <input value={value} onChange={onChange} type={type} placeholder={placeholder} className="w-full rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm text-slate-700 outline-none focus:border-orange-400" />
    </div>
  )
}

const OFFICE_TIMEZONES = ['Not set — the CRM uses UTC', 'Pacific — America/Los_Angeles', 'Mountain — America/Denver', 'Central — America/Chicago', 'Eastern — America/New_York', 'UTC']
// Grouped CRM time-zone options (the "Detected" group is filled from the browser at render).
const CRM_TZ_GROUPS = [
  { group: 'United States', zones: ['Eastern — New York, Atlanta, Miami', 'Central — Chicago, Dallas, Houston', 'Mountain — Denver, Salt Lake City', 'Arizona — Phoenix, Tucson (no DST)', 'Pacific — Los Angeles, Seattle', 'Alaska — Anchorage', 'Hawaii — Honolulu (no DST)'] },
  { group: 'Canada', zones: ['Eastern — Toronto, Ottawa', 'Central — Winnipeg', 'Mountain — Calgary, Edmonton', 'Pacific — Vancouver', 'Atlantic — Halifax'] },
  { group: 'Other', zones: ['Mexico City', 'London', 'UTC — no local calendar'] },
]

function ProfileSectionHead({ icon: Icon, tone, title, sub }) {
  return (
    <div className="flex items-start gap-3">
      <span className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-lg ${tone}`}><Icon className="h-5 w-5" /></span>
      <div>
        <p className="text-sm font-bold uppercase tracking-wide text-slate-800">{title}</p>
        {sub && <p className="text-xs text-slate-400">{sub}</p>}
      </div>
    </div>
  )
}

function ProfileField({ label, value, onChange, type = 'text', placeholder, hint, disabled }) {
  return (
    <div>
      <label className="mb-1 block text-xs font-semibold text-slate-500">{label}</label>
      <input value={value} onChange={onChange} type={type} placeholder={placeholder} disabled={disabled} className={`w-full rounded-lg border px-3 py-2 text-sm outline-none focus:border-orange-400 ${disabled ? 'cursor-not-allowed border-slate-200 bg-slate-50 text-slate-500' : 'border-slate-300 bg-white text-slate-700'}`} />
      {hint && <p className="mt-1 text-xs text-slate-400">{hint}</p>}
    </div>
  )
}

function ProfileSettingsPage({ user }) {
  const notify = useToast()
  const [form, setForm] = usePersistentState('profile_settings', {
    firstName: (user?.name || CURRENT_USER.name).split(' ')[0] || '',
    lastName: (user?.name || CURRENT_USER.name).split(' ').slice(1).join(' ') || '',
    phone: '', phoneType: '', title: 'Agent', license: '', crmTz: '', bio: '',
    companyName: '', companyLicense: '', officePhone: '', website: '', officeAddress: '', city: '', state: '', zip: '', officeTz: OFFICE_TIMEZONES[0],
    photo: '', logo: '',
  })
  const email = user?.email || CURRENT_USER.email
  const [pw, setPw] = useState({ current: '', next: '', confirm: '' })
  const [delOpen, setDelOpen] = useState(false)
  const [delText, setDelText] = useState('')
  const set = (k) => (e) => setForm((f) => ({ ...f, [k]: e.target.value }))
  const setP = (k) => (e) => setPw((p) => ({ ...p, [k]: e.target.value }))
  const initials = ((form.firstName || '') + ' ' + (form.lastName || '')).trim().split(' ').map((n) => n[0]).join('').slice(0, 2).toUpperCase() || 'U'
  const detectedTz = (() => { try { return Intl.DateTimeFormat().resolvedOptions().timeZone } catch { return 'UTC' } })()
  const detectedOpt = `${detectedTz} — from this browser`
  const photoRef = useRef(null)
  const logoRef = useRef(null)
  const readImage = (file, key) => {
    if (!file) return
    if (!file.type.startsWith('image/')) { notify('Please choose an image file', 'error'); return }
    if (file.size > 3 * 1024 * 1024) { notify('Image must be under 3 MB', 'error'); return }
    const reader = new FileReader()
    reader.onload = () => { setForm((f) => ({ ...f, [key]: reader.result })); notify(key === 'photo' ? 'Photo updated' : 'Logo updated') }
    reader.readAsDataURL(file)
  }
  const sel = 'w-full rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm text-slate-700 outline-none focus:border-orange-400'
  const toolBtn = 'flex h-7 w-7 items-center justify-center rounded text-slate-500 transition hover:bg-slate-100 hover:text-slate-700'

  const changePw = () => {
    if (!pw.current || !pw.next) { notify('Fill in your current and new password', 'error'); return }
    if (pw.next !== pw.confirm) { notify('New passwords do not match', 'error'); return }
    setPw({ current: '', next: '', confirm: '' })
    notify('Password updated')
  }

  return (
    <div className="mx-auto max-w-[900px] p-6">
      <h1 className="text-2xl font-extrabold text-slate-900">Profile Settings</h1>
      <p className="text-sm text-slate-500">Changes are applied to all your marketing documents.</p>

      {/* PERSONAL INFORMATION */}
      <div className="mt-6 overflow-hidden rounded-xl border border-slate-200 border-l-4 border-l-blue-400 bg-white p-5 shadow-sm">
        <ProfileSectionHead icon={User} tone="bg-blue-50 text-blue-500" title="Personal information" />
        <div className="mt-5 flex items-center gap-4">
          <button type="button" onClick={() => photoRef.current && photoRef.current.click()} className="flex h-16 w-16 items-center justify-center overflow-hidden rounded-full bg-gradient-to-br from-orange-400 to-orange-600 text-lg font-bold text-white ring-2 ring-orange-200 transition hover:opacity-90">{form.photo ? <img src={form.photo} alt="" className="h-full w-full object-cover" /> : initials}</button>
          <input ref={photoRef} type="file" accept="image/*" className="hidden" onChange={(e) => { readImage(e.target.files[0], 'photo'); e.target.value = '' }} />
          <div>
            <p className="text-sm font-semibold text-slate-600">Profile Photo</p>
            <div className="flex items-center gap-2">
              <button onClick={() => photoRef.current && photoRef.current.click()} className="text-sm font-semibold text-brand hover:underline">Upload</button>
              {form.photo && <button onClick={() => setForm((f) => ({ ...f, photo: '' }))} className="text-sm font-semibold text-slate-400 hover:text-rose-500">Remove</button>}
            </div>
          </div>
        </div>
        <div className="mt-5 grid gap-4 sm:grid-cols-2">
          <ProfileField label="First Name" value={form.firstName} onChange={set('firstName')} placeholder="First name" />
          <ProfileField label="Last Name" value={form.lastName} onChange={set('lastName')} placeholder="Last name" />
          <ProfileField label="Email" value={email} onChange={() => {}} disabled hint="Cannot be changed" />
          <ProfileField label="Phone" value={form.phone} onChange={set('phone')} placeholder="(602) 555-0100" />
          <div>
            <label className="mb-1 block text-xs font-semibold text-slate-500">Phone Type</label>
            <select value={form.phoneType} onChange={set('phoneType')} className={sel}><option value="">Select…</option>{['Mobile', 'Office', 'Home', 'Direct'].map((o) => <option key={o}>{o}</option>)}</select>
          </div>
          <ProfileField label="Title" value={form.title} onChange={set('title')} placeholder="Agent" />
          <ProfileField label="License #" value={form.license} onChange={set('license')} placeholder="e.g. DRE# 01234567" />
        </div>
        <div className="mt-4">
          <label className="mb-1 block text-xs font-semibold text-slate-500">CRM time zone</label>
          <select value={form.crmTz || detectedOpt} onChange={set('crmTz')} className={sel}>
            <optgroup label="Detected"><option value={detectedOpt}>{detectedOpt}</option></optgroup>
            {CRM_TZ_GROUPS.map((g) => <optgroup key={g.group} label={g.group}>{g.zones.map((z) => <option key={z} value={z}>{z}</option>)}</optgroup>)}
          </select>
          <p className="mt-1 text-xs text-slate-400">Sets what day the CRM calls "today" — due dates, the week's tasks, and the countdown to a lease expiring. Only override this if you work in a different time zone from your office.</p>
        </div>
        <div className="mt-4">
          <div className="mb-1 flex items-center justify-between">
            <label className="text-xs font-semibold text-slate-500">Bio</label>
            <span className="text-xs text-slate-400">Appears on the Advisor Bio / Closing page of your documents (currently the CS template).</span>
          </div>
          <div className="rounded-lg border border-slate-300 focus-within:border-orange-400">
            <div className="flex items-center gap-1 border-b border-slate-200 px-2 py-1.5">
              <button className={toolBtn} title="Bold"><Bold className="h-3.5 w-3.5" /></button>
              <button className={toolBtn} title="Italic"><Italic className="h-3.5 w-3.5" /></button>
              <button className={toolBtn} title="Underline"><Underline className="h-3.5 w-3.5" /></button>
              <span className="mx-1 h-4 w-px bg-slate-200" />
              <button className={toolBtn} title="Bulleted list"><List className="h-3.5 w-3.5" /></button>
              <button className={toolBtn} title="Numbered list"><ListOrdered className="h-3.5 w-3.5" /></button>
              <button className={toolBtn} title="Link"><Link2 className="h-3.5 w-3.5" /></button>
              <span className="mx-1 h-4 w-px bg-slate-200" />
              <button className={toolBtn} title="Undo"><Undo2 className="h-3.5 w-3.5" /></button>
              <button className={toolBtn} title="Redo"><Redo2 className="h-3.5 w-3.5" /></button>
              <span className="ml-auto text-xs text-slate-400">{(form.bio || '').length}/4000</span>
            </div>
            <textarea value={form.bio} onChange={set('bio')} maxLength={4000} rows={5} placeholder="A brief professional background — your experience, designations (SIOR, CCIM), notable closings, education, community involvement." className="w-full resize-y rounded-b-lg bg-white px-3 py-2 text-sm leading-relaxed text-slate-700 outline-none" />
          </div>
        </div>
      </div>

      {/* COMPANY INFORMATION */}
      <div className="mt-5 overflow-hidden rounded-xl border border-slate-200 border-l-4 border-l-emerald-400 bg-white p-5 shadow-sm">
        <ProfileSectionHead icon={Building2} tone="bg-emerald-50 text-emerald-500" title="Company information" sub="This info appears in your marketing documents." />
        <div className="mt-5 flex items-center gap-4">
          <button type="button" onClick={() => logoRef.current && logoRef.current.click()} className="flex h-16 w-16 items-center justify-center overflow-hidden rounded-lg border border-dashed border-slate-300 bg-slate-50 text-slate-300 transition hover:border-orange-400 hover:text-orange-400">{form.logo ? <img src={form.logo} alt="" className="h-full w-full object-contain" /> : <ImageIcon className="h-6 w-6" />}</button>
          <input ref={logoRef} type="file" accept="image/*" className="hidden" onChange={(e) => { readImage(e.target.files[0], 'logo'); e.target.value = '' }} />
          <div>
            <p className="text-sm font-semibold text-slate-600">Company Logo</p>
            <div className="flex items-center gap-2">
              <button onClick={() => logoRef.current && logoRef.current.click()} className="text-sm font-semibold text-brand hover:underline">Upload</button>
              {form.logo && <button onClick={() => setForm((f) => ({ ...f, logo: '' }))} className="text-sm font-semibold text-slate-400 hover:text-rose-500">Remove</button>}
            </div>
          </div>
        </div>
        <div className="mt-5 grid gap-4 sm:grid-cols-2">
          <ProfileField label="Company Name" value={form.companyName} onChange={set('companyName')} placeholder="Company name" />
          <ProfileField label="Company License #" value={form.companyLicense} onChange={set('companyLicense')} placeholder="e.g. BRE# 01234567" />
          <ProfileField label="Office Phone" value={form.officePhone} onChange={set('officePhone')} placeholder="(602) 555-0100" />
          <ProfileField label="Website" value={form.website} onChange={set('website')} placeholder="https://" />
        </div>
        <div className="mt-4"><ProfileField label="Office Address" value={form.officeAddress} onChange={set('officeAddress')} placeholder="Street address" /></div>
        <div className="mt-4 grid gap-4 sm:grid-cols-3">
          <ProfileField label="City" value={form.city} onChange={set('city')} placeholder="City" />
          <div>
            <label className="mb-1 block text-xs font-semibold text-slate-500">State</label>
            <select value={form.state} onChange={set('state')} className={sel}><option value="">Select…</option>{US_STATES.map((s) => <option key={s}>{s}</option>)}</select>
          </div>
          <ProfileField label="Zip Code" value={form.zip} onChange={set('zip')} placeholder="Zip" />
        </div>
        <div className="mt-4">
          <label className="mb-1 block text-xs font-semibold text-slate-500">Office time zone</label>
          <select value={form.officeTz} onChange={set('officeTz')} className={sel}>{OFFICE_TIMEZONES.map((t) => <option key={t}>{t}</option>)}</select>
          <p className="mt-1 text-xs text-slate-400">The default for everyone on the team. Leaving it unset means the CRM ends the day at UTC midnight, which is the afternoon before in North America.</p>
        </div>
        <div className="mt-5 flex justify-end">
          <PrimaryButton icon={Check} onClick={() => notify('Profile updated successfully. All documents have been updated.', 'success')}>Save Changes</PrimaryButton>
        </div>
      </div>

      {/* CHANGE PASSWORD */}
      <div className="mt-5 overflow-hidden rounded-xl border border-slate-200 border-l-4 border-l-amber-400 bg-white p-5 shadow-sm">
        <ProfileSectionHead icon={Lock} tone="bg-amber-50 text-amber-500" title="Change password" />
        <div className="mt-5 grid gap-4 sm:grid-cols-3">
          <ProfileField label="Current Password" value={pw.current} onChange={setP('current')} type="password" placeholder="••••••••" />
          <ProfileField label="New Password" value={pw.next} onChange={setP('next')} type="password" placeholder="••••••••" />
          <ProfileField label="Confirm New" value={pw.confirm} onChange={setP('confirm')} type="password" placeholder="••••••••" />
        </div>
        <div className="mt-4 flex justify-end">
          <button onClick={changePw} className="rounded-lg border border-slate-300 px-4 py-2 text-sm font-semibold text-slate-700 transition hover:bg-slate-50">Change Password</button>
        </div>
      </div>

      {/* DELETE ACCOUNT */}
      <div className="mt-5 overflow-hidden rounded-xl border border-slate-200 border-l-4 border-l-rose-400 bg-white p-5 shadow-sm">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <ProfileSectionHead icon={Trash2} tone="bg-rose-50 text-rose-500" title="Delete account" sub="Permanently delete your account and all associated data." />
          <button onClick={() => { setDelOpen(true); setDelText('') }} className="text-sm font-semibold text-rose-500 hover:underline">Delete My Account</button>
        </div>
      </div>

      {/* Delete confirm */}
      {delOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4" onClick={() => setDelOpen(false)}>
          <div className="w-full max-w-md rounded-xl bg-white p-6 shadow-2xl" onClick={(e) => e.stopPropagation()}>
            <div className="flex items-start gap-3">
              <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-rose-50 text-rose-500"><Trash2 className="h-5 w-5" /></span>
              <div>
                <p className="text-sm font-bold text-slate-900">Delete your account?</p>
                <p className="mt-1 text-sm text-slate-500">This permanently deletes your account and all associated data — deals, contacts, documents. This cannot be undone.</p>
              </div>
            </div>
            <label className="mt-4 block text-xs font-semibold text-slate-500">Type <span className="font-mono text-rose-500">DELETE</span> to confirm</label>
            <input value={delText} onChange={(e) => setDelText(e.target.value)} placeholder="DELETE" className="mt-1 w-full rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm outline-none focus:border-rose-400" />
            <div className="mt-4 flex justify-end gap-2">
              <button onClick={() => setDelOpen(false)} className="rounded-lg border border-slate-200 px-4 py-2 text-sm font-semibold text-slate-700 transition hover:bg-slate-50">Cancel</button>
              <button disabled={delText !== 'DELETE'} onClick={() => { setDelOpen(false); notify('Account deletion requested — demo', 'error') }} className={`rounded-lg px-4 py-2 text-sm font-semibold text-white transition ${delText === 'DELETE' ? 'bg-rose-500 hover:bg-rose-600' : 'cursor-not-allowed bg-rose-300'}`}>Delete My Account</button>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

const TEAM_SETTINGS_MEMBERS = [
  { id: 'u1', name: 'Neil Naran', email: 'Nel@valuereis.com', role: 'Admin', docs: 16, active: 'Aug 11', you: true, initials: 'N' },
]
const TEAM_ROLES = ['Member', 'Admin', 'Coordinator']
const TEAM_ROLE_LEGEND = [
  { role: 'Member', desc: 'Own documents, all features. Paid seat.' },
  { role: 'Admin', desc: 'Member + team management/billing.' },
  { role: 'Coordinator', desc: 'Creates docs on behalf of others. Free seat.' },
]
const BROKER_FLOWS = {
  property: { label: 'Property', stages: ['Inquiry', 'NDA Signed', 'Tour', 'LOI', 'Under Contract'], desc: '' },
  businesses: { label: 'Businesses', stages: ['Inquiry', 'NDA Sent', 'NDA Signed', 'CIM Sent', 'LOI'], desc: 'For brokers selling restaurants, bars, shops and other going concerns, where a buyer signs an NDA and then receives a CIM.' },
}
const DEFAULT_CA_TEXT = `The information contained in the following offering memorandum is proprietary and strictly confidential. It is intended to be reviewed only by the party receiving it from [COMPANY_NAME] and should not be made available to any other person or entity without the written consent of [COMPANY_NAME].

By taking possession of and reviewing the information contained herein the recipient agrees to hold and treat all such information in the strictest confidence. The recipient further agrees that recipient will not photocopy or duplicate any part of the offering memorandum. If you have no interest in the subject property, please promptly return this offering memorandum to [COMPANY_NAME]. This offering memorandum has been prepared to provide summary, unverified financial and physical information to prospective purchasers, and to establish only a preliminary level of interest in the subject property. The information contained herein is not a substitute for a thorough due diligence investigation. [COMPANY_NAME] has not made any investigation, and makes no warranty or representation with respect to the income or expenses for the subject property, the future projected financial performance of the property, the size and square footage of the property and improvements, the presence or absence of contaminating substances, PCBs or asbestos, the compliance with local, state and federal regulations, the physical condition of the improvements thereon, or financial condition or business prospects of any tenant, or any tenant's plans or intentions to continue its occupancy of the subject property. The information contained in this offering memorandum has been obtained from sources we believe reliable; however, [COMPANY_NAME] has not verified, and will not verify, any of the information contained herein, nor has [COMPANY_NAME] conducted any investigation regarding these matters and makes no warranty or representation whatsoever regarding the accuracy or completeness of the information provided. All potential buyers must take appropriate measures to verify all of the information set forth herein. Prospective buyers shall be responsible for their costs and expenses of investigating the subject property.

PROPERTY SHOWINGS ARE BY APPOINTMENT ONLY.
PLEASE CONTACT THE [COMPANY_NAME] ADVISOR FOR MORE DETAILS.`
const CA_TEMPLATES = [
  { name: 'Standard Offering Memorandum CA', text: DEFAULT_CA_TEXT },
  { name: 'Short-form NDA', text: `This Confidentiality Agreement is entered into between the recipient and [COMPANY_NAME]. The recipient agrees to keep all information regarding the subject property strictly confidential and to use it solely to evaluate a potential transaction.\n\nPLEASE CONTACT THE [COMPANY_NAME] ADVISOR FOR MORE DETAILS.` },
  { name: 'Business (going-concern) CA', text: `The information regarding this business is confidential. By signing, the recipient agrees not to contact employees, landlords, customers, or suppliers, and to hold all financials and the identity of the business in strict confidence, as required by [COMPANY_NAME].\n\nPLEASE CONTACT THE [COMPANY_NAME] ADVISOR FOR MORE DETAILS.` },
]

function TeamSettingsPage({ role = 'Member' }) {
  const isAdminUp = ['Owner', 'Admin'].includes(role)
  const notify = useToast()
  const [members, setMembers] = usePersistentState('team_members', TEAM_SETTINGS_MEMBERS)
  const [brokerType, setBrokerType] = usePersistentState('team_broker', 'property')
  const [savedCa, setSavedCa] = usePersistentState('team_ca', DEFAULT_CA_TEXT)
  const [caDraft, setCaDraft] = useState(savedCa)
  const [tplOpen, setTplOpen] = useState(false)
  const [inviteOpen, setInviteOpen] = useState(false)
  const [inviteStep, setInviteStep] = useState(1)
  const [inviteEmails, setInviteEmails] = useState([])
  const [inviteInput, setInviteInput] = useState('')
  const [inviteRole, setInviteRole] = useState('Member')
  const commitEmail = () => { const e = inviteInput.trim().replace(/,$/, '').trim(); if (e && /\S+@\S+\.\S+/.test(e) && !inviteEmails.includes(e)) { setInviteEmails((l) => [...l, e]); setInviteInput('') } else if (e) { notify('Enter a valid email', 'error') } }
  const sendInvites = () => {
    if (!inviteEmails.length) { notify('Add at least one email', 'error'); return }
    setMembers((l) => [...l, ...inviteEmails.map((em) => ({ id: uid(), name: em.split('@')[0], email: em, role: inviteRole, docs: 0, active: 'Invited', you: false, initials: em.slice(0, 1).toUpperCase() }))])
    notify(`${inviteEmails.length} invite${inviteEmails.length === 1 ? '' : 's'} sent`)
    setInviteOpen(false)
  }
  const setRole = (id, role) => { setMembers((l) => l.map((m) => (m.id === id ? { ...m, role } : m))); notify('Role updated') }
  const [editMember, setEditMember] = useState(null)   // member being edited (name/email)
  const [confirmDel, setConfirmDel] = useState(null)   // member pending delete confirmation
  const saveMember = () => {
    if (!editMember.name.trim()) { notify('Name is required', 'error'); return }
    setMembers((l) => l.map((m) => (m.id === editMember.id ? { ...m, name: editMember.name.trim(), email: editMember.email.trim(), initials: (editMember.name.trim()[0] || '?').toUpperCase() } : m)))
    setEditMember(null)
    notify('Member updated')
  }
  const deleteMember = () => {
    setMembers((l) => l.filter((m) => m.id !== confirmDel.id))
    notify(`Removed ${confirmDel.name}`, 'error')
    setConfirmDel(null)
  }
  const seats = members.length
  const unsaved = caDraft !== savedCa
  const toolBtn = 'flex h-7 w-7 items-center justify-center rounded text-slate-500 transition hover:bg-slate-100 hover:text-slate-700'
  const th = 'px-4 py-3 text-left text-[11px] font-semibold uppercase tracking-wide text-slate-400'
  const td = 'px-4 py-3 text-sm text-slate-700'

  return (
    <div className="mx-auto max-w-[1600px] p-6">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div className="flex items-center gap-3">
          <h1 className="text-2xl font-extrabold text-slate-900">Team Management</h1>
        </div>
      </div>
      <p className="mt-1 text-sm text-slate-500">Manage team members and roles from the <span className="font-semibold text-brand">Team &amp; Permissions</span> page.</p>

      {/* Embed on your website (moved here from My Deals — Admin/Owner only) */}
      {isAdminUp && (() => {
        let saved = {}
        try { saved = JSON.parse(localStorage.getItem('crebuilder_hub') || '{}') } catch { saved = {} }
        const hubUrl = `${window.location.origin}${window.location.pathname}?hub=vaziamts`
        const embedUrl = `${hubUrl}&t=${encodeURIComponent(saved.template || 'Modern')}&c=${(saved.primary || '#0f172a').replace('#', '')}&v=${encodeURIComponent(saved.defaultView || 'mapgrid')}`
        const embedCode = `<iframe id="cre-listings" src="${embedUrl}" width="100%" height="900" frameborder="0" style="border:none;border-radius:8px" title="Property Listings"></iframe>`
        return (
          <div className="mt-5 rounded-xl border border-slate-200 bg-white p-5 shadow-sm">
            <div className="flex items-start gap-2">
              <Code2 className="mt-0.5 h-5 w-5 text-slate-400" />
              <div><p className="text-sm font-bold text-slate-900">Embed on your website</p><p className="text-xs text-slate-400">Paste this snippet into your site to show your live listings. Only Admins &amp; Owners can access this.</p></div>
            </div>
            <pre className="scrollbar-slim mt-3 overflow-x-auto rounded-lg bg-slate-900 p-3 text-xs text-slate-200"><code>{embedCode}</code></pre>
            <div className="mt-3 flex flex-wrap items-center gap-2">
              <button onClick={() => { copyToClipboard(embedCode); notify('Embed code copied') }} className="inline-flex items-center gap-1.5 rounded-lg bg-brand px-3 py-2 text-sm font-semibold text-white transition hover:bg-brand-hover"><Copy className="h-4 w-4" /> Copy embed code</button>
              <a href={embedUrl} target="_blank" rel="noreferrer" className="inline-flex items-center gap-1.5 rounded-lg border border-slate-200 px-3 py-2 text-sm font-semibold text-slate-700 transition hover:bg-slate-50"><ExternalLink className="h-4 w-4" /> Preview</a>
            </div>
          </div>
        )
      })()}

      {/* Appearance (moved here from My Deals — Admin/Owner only) */}
      {isAdminUp && <AppearanceSettings />}

      {/* What do you broker? */}
      <div className="mt-5 rounded-xl border border-slate-200 bg-white p-5 shadow-sm">
        <div className="flex items-start gap-2">
          <Building2 className="mt-0.5 h-5 w-5 text-slate-400" />
          <div><p className="text-sm font-bold text-slate-900">What do you broker?</p><p className="text-xs text-slate-400">See the deal stages your whole team works in.</p></div>
        </div>
        <div className="mt-4 space-y-3">
          {Object.entries(BROKER_FLOWS).map(([key, f]) => {
            const selected = brokerType === key
            return (
              <div key={key} className={`rounded-xl border p-4 ${selected ? 'border-orange-300 bg-orange-50/40' : 'border-slate-200'}`}>
                <p className={`text-sm font-bold ${selected ? 'text-brand' : 'text-slate-700'}`}>{f.label}{selected && <span className="font-normal text-slate-400"> — currently selected</span>}</p>
                <p className="mt-1 flex flex-wrap items-center gap-1.5 text-sm text-slate-600">{f.stages.map((s, i) => (<span key={s} className="flex items-center gap-1.5">{i > 0 && <ArrowRight className="h-3.5 w-3.5 text-slate-300" />}{s}</span>))}</p>
                {f.desc && <p className="mt-2 text-xs text-slate-400">{f.desc}</p>}
              </div>
            )
          })}
        </div>
        <button onClick={() => { const next = brokerType === 'property' ? 'businesses' : 'property'; setBrokerType(next); notify(`Switched to ${BROKER_FLOWS[next].label.toLowerCase()}`) }} className="mt-3 rounded-lg border border-slate-300 px-4 py-2 text-sm font-semibold text-slate-700 transition hover:bg-slate-50">Switch to {brokerType === 'property' ? 'businesses' : 'property'}</button>
      </div>

      {/* Company Confidentiality Agreement */}
      <div className="mt-5 rounded-xl border border-slate-200 bg-white p-5 shadow-sm">
        <div className="flex flex-wrap items-start justify-between gap-3">
          <div className="flex items-start gap-2">
            <FileText className="mt-0.5 h-5 w-5 text-slate-400" />
            <div><p className="text-sm font-bold text-slate-900">Company Confidentiality Agreement</p><p className="text-xs text-slate-400">Set the default agreement enforced on all team member documents.</p></div>
          </div>
          <div className="flex items-center gap-3">
            {unsaved && <span className="text-xs font-semibold text-amber-600">Unsaved</span>}
            <div className="relative">
              <button onClick={() => setTplOpen((v) => !v)} className="inline-flex items-center gap-1.5 rounded-lg border border-slate-200 px-3 py-1.5 text-sm font-semibold text-slate-700 transition hover:bg-slate-50"><FileText className="h-4 w-4" /> Templates <ChevronDown className="h-3.5 w-3.5" /></button>
              {tplOpen && (
                <div className="absolute right-0 z-20 mt-1 w-64 overflow-hidden rounded-lg border border-slate-200 bg-white shadow-lg">
                  {CA_TEMPLATES.map((t) => (
                    <button key={t.name} onClick={() => { setCaDraft(t.text); setTplOpen(false); notify(`Loaded: ${t.name}`) }} className="block w-full px-3 py-2 text-left text-sm text-slate-700 transition hover:bg-slate-50">{t.name}</button>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>
        <div className="mt-4 rounded-lg border border-slate-300 focus-within:border-orange-400">
          <div className="flex items-center gap-1 border-b border-slate-200 px-2 py-1.5">
            <button className={toolBtn} title="Bold"><Bold className="h-3.5 w-3.5" /></button>
            <button className={toolBtn} title="Italic"><Italic className="h-3.5 w-3.5" /></button>
            <button className={toolBtn} title="Underline"><Underline className="h-3.5 w-3.5" /></button>
            <span className="mx-1 h-4 w-px bg-slate-200" />
            <button className={toolBtn} title="Bulleted list"><List className="h-3.5 w-3.5" /></button>
            <button className={toolBtn} title="Numbered list"><ListOrdered className="h-3.5 w-3.5" /></button>
            <button className={toolBtn} title="Link"><Link2 className="h-3.5 w-3.5" /></button>
            <span className="mx-1 h-4 w-px bg-slate-200" />
            <button className={toolBtn} title="Undo"><Undo2 className="h-3.5 w-3.5" /></button>
            <button className={toolBtn} title="Redo"><Redo2 className="h-3.5 w-3.5" /></button>
          </div>
          <textarea value={caDraft} onChange={(e) => setCaDraft(e.target.value)} rows={16} className="w-full resize-y rounded-b-lg bg-white px-4 py-3 text-sm leading-relaxed text-brand outline-none" />
        </div>
        <div className="mt-4 flex flex-wrap items-center justify-between gap-3">
          <p className="inline-flex items-center gap-1.5 text-xs font-semibold text-slate-500"><Lock className="h-3.5 w-3.5" /> Enforced on all team member documents</p>
          <div className="flex items-center gap-2">
            <button onClick={() => { setCaDraft(''); setSavedCa(''); notify('Agreement removed', 'error') }} className="rounded-lg border border-slate-300 px-4 py-2 text-sm font-semibold text-slate-700 transition hover:bg-slate-50">Remove Agreement</button>
            <PrimaryButton icon={Check} onClick={() => { setSavedCa(caDraft); notify('Agreement saved. All team member documents updated.', 'success') }}>Save Agreement</PrimaryButton>
          </div>
        </div>
        <p className="mt-2 text-xs text-slate-400">This agreement will appear on all team member documents and cannot be changed by members.</p>
      </div>

      {/* Invite Member modal */}
      {inviteOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4" onClick={() => setInviteOpen(false)}>
          <div className="w-full max-w-lg rounded-2xl bg-white p-7 shadow-2xl" onClick={(e) => e.stopPropagation()}>
            <div className="flex items-start justify-between">
              <p className="text-xs font-bold uppercase tracking-wide text-brand">Team · Step {inviteStep} of 2</p>
              <button onClick={() => setInviteOpen(false)} className="text-slate-400 hover:text-slate-700"><X className="h-5 w-5" /></button>
            </div>
            {inviteStep === 1 ? (
              <>
                <h2 className="mt-2 text-2xl font-extrabold text-slate-900">Invite team members</h2>
                <p className="mt-2 text-sm text-slate-500">Each new member gets their own login, document workspace, and full Pro access.</p>
                <div className="mt-6 flex items-center justify-between">
                  <label className="text-xs font-bold uppercase tracking-wide text-slate-500">Email address</label>
                  <span className="text-xs text-slate-400">Enter or comma to add</span>
                </div>
                <div className="mt-1 flex flex-wrap items-center gap-2 rounded-lg border border-slate-300 px-3 py-2.5 focus-within:border-orange-400">
                  {inviteEmails.map((em) => (
                    <span key={em} className="inline-flex items-center gap-1 rounded-full bg-orange-50 px-2 py-0.5 text-xs font-semibold text-brand">{em}<button onClick={() => setInviteEmails((l) => l.filter((x) => x !== em))} className="text-brand/60 hover:text-brand"><X className="h-3 w-3" /></button></span>
                  ))}
                  <input value={inviteInput} onChange={(e) => setInviteInput(e.target.value)} onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ',') { e.preventDefault(); commitEmail() } }} onBlur={commitEmail} placeholder={inviteEmails.length ? '' : 'colleague@company.com'} className="min-w-[160px] flex-1 bg-transparent text-sm outline-none placeholder:text-slate-400" />
                </div>
                <p className="mt-6 text-xs font-bold uppercase tracking-wide text-slate-500">Role guide</p>
                <div className="mt-2 space-y-2.5">
                  {[{ r: 'Member', dot: 'bg-slate-400', d: 'Own documents, all features. Paid seat.' }, { r: 'Admin', dot: 'bg-orange-500', d: 'Everything a Member has, plus team management & billing.' }, { r: 'Coordinator', dot: 'bg-emerald-500', d: 'Creates documents on behalf of others. Free seat.' }].map((x) => (
                    <div key={x.r} className="flex gap-3 text-sm">
                      <span className={`mt-1.5 h-2 w-2 shrink-0 rounded-full ${x.dot}`} />
                      <p><span className="font-bold text-slate-800">{x.r}</span> <span className="ml-8 text-slate-500">{x.d}</span></p>
                    </div>
                  ))}
                </div>
                <div className="mt-7 flex items-center justify-end gap-3">
                  <button onClick={() => setInviteOpen(false)} className="text-sm font-semibold text-slate-500 hover:text-slate-800">Cancel</button>
                  <button onClick={() => { commitEmail(); if (inviteEmails.length || /\S+@\S+\.\S+/.test(inviteInput)) setInviteStep(2); else notify('Add at least one email', 'error') }} className="inline-flex items-center gap-1.5 rounded-lg bg-brand px-5 py-2.5 text-sm font-bold text-white transition hover:bg-brand-hover">Continue <ArrowRight className="h-4 w-4" /></button>
                </div>
              </>
            ) : (
              <>
                <h2 className="mt-2 text-2xl font-extrabold text-slate-900">Assign a role</h2>
                <p className="mt-2 text-sm text-slate-500">Inviting <span className="font-semibold text-slate-700">{inviteEmails.length} {inviteEmails.length === 1 ? 'person' : 'people'}</span> — pick the role they'll start with.</p>
                <div className="mt-4 flex flex-wrap gap-2">{inviteEmails.map((em) => <span key={em} className="rounded-full bg-slate-100 px-2.5 py-1 text-xs font-semibold text-slate-600">{em}</span>)}</div>
                <p className="mt-6 text-xs font-bold uppercase tracking-wide text-slate-500">Role</p>
                <div className="mt-2 space-y-2">
                  {[{ r: 'Member', d: 'Own documents, all features. Paid seat.' }, { r: 'Admin', d: 'Everything a Member has, plus team management & billing.' }, { r: 'Coordinator', d: 'Creates documents on behalf of others. Free seat.' }].map((x) => (
                    <button key={x.r} onClick={() => setInviteRole(x.r)} className={`flex w-full items-start gap-3 rounded-xl border p-3 text-left transition ${inviteRole === x.r ? 'border-orange-300 bg-orange-50/50' : 'border-slate-200 hover:bg-slate-50'}`}>
                      <span className={`mt-0.5 flex h-4 w-4 shrink-0 items-center justify-center rounded-full border-2 ${inviteRole === x.r ? 'border-brand' : 'border-slate-300'}`}>{inviteRole === x.r && <span className="h-2 w-2 rounded-full bg-brand" />}</span>
                      <p className="text-sm"><span className="font-bold text-slate-800">{x.r}</span> <span className="text-slate-500">— {x.d}</span></p>
                    </button>
                  ))}
                </div>
                <div className="mt-7 flex items-center justify-between gap-3">
                  <button onClick={() => setInviteStep(1)} className="inline-flex items-center gap-1.5 text-sm font-semibold text-slate-500 hover:text-slate-800"><ArrowLeft className="h-4 w-4" /> Back</button>
                  <button onClick={sendInvites} className="inline-flex items-center gap-1.5 rounded-lg bg-brand px-5 py-2.5 text-sm font-bold text-white transition hover:bg-brand-hover">Send {inviteEmails.length} invite{inviteEmails.length === 1 ? '' : 's'}</button>
                </div>
              </>
            )}
          </div>
        </div>
      )}

      {/* Edit member modal */}
      {editMember && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 p-4">
          <div className="w-full max-w-md rounded-2xl bg-white p-6 shadow-xl">
            <div className="flex items-center justify-between"><p className="text-lg font-bold text-slate-900">Edit member</p><button onClick={() => setEditMember(null)} className="text-slate-400 hover:text-slate-700"><X className="h-5 w-5" /></button></div>
            <div className="mt-4 space-y-3">
              <div><label className="mb-1 block text-xs font-semibold text-slate-500">Name</label><input value={editMember.name} onChange={(e) => setEditMember((m) => ({ ...m, name: e.target.value }))} className="w-full rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm outline-none focus:border-orange-400" /></div>
              <div><label className="mb-1 block text-xs font-semibold text-slate-500">Email</label><input type="email" value={editMember.email} onChange={(e) => setEditMember((m) => ({ ...m, email: e.target.value }))} className="w-full rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm outline-none focus:border-orange-400" /></div>
            </div>
            <div className="mt-5 flex justify-end gap-2"><button onClick={() => setEditMember(null)} className="rounded-lg border border-slate-200 px-4 py-2 text-sm font-semibold text-slate-700 hover:bg-slate-50">Cancel</button><button onClick={saveMember} className="rounded-lg bg-brand px-4 py-2 text-sm font-bold text-white hover:bg-brand-hover">Save</button></div>
          </div>
        </div>
      )}

      {/* Delete member confirm */}
      {confirmDel && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 p-4">
          <div className="w-full max-w-sm rounded-2xl bg-white p-6 shadow-xl">
            <div className="flex items-center gap-3"><span className="flex h-10 w-10 items-center justify-center rounded-full bg-rose-50 text-rose-500"><Trash2 className="h-5 w-5" /></span><div><p className="text-base font-bold text-slate-900">Remove member?</p><p className="text-sm text-slate-500">{confirmDel.name} ({confirmDel.email}) will lose access.</p></div></div>
            <div className="mt-5 flex justify-end gap-2"><button onClick={() => setConfirmDel(null)} className="rounded-lg border border-slate-200 px-4 py-2 text-sm font-semibold text-slate-700 hover:bg-slate-50">Cancel</button><button onClick={deleteMember} className="rounded-lg bg-rose-600 px-4 py-2 text-sm font-bold text-white hover:bg-rose-700">Remove</button></div>
          </div>
        </div>
      )}
    </div>
  )
}

function NoAccessPage() {
  return (
    <div className="flex h-full flex-col items-center justify-center p-6 text-center">
      <div className="flex h-16 w-16 items-center justify-center rounded-2xl bg-slate-100 text-slate-400">
        <Ban className="h-8 w-8" />
      </div>
      <h1 className="mt-5 text-2xl font-extrabold text-slate-900">Restricted</h1>
      <p className="mt-2 max-w-md text-sm text-slate-500">This page is available to Owners and Admins only. Contact your account owner if you need access.</p>
    </div>
  )
}

function PlaceholderPage({ label, icon: Icon }) {
  const notify = useToast()
  return (
    <div className="flex h-full flex-col items-center justify-center p-6 text-center">
      <div className="flex h-16 w-16 items-center justify-center rounded-2xl bg-orange-50 text-brand">
        <Icon className="h-8 w-8" />
      </div>
      <h1 className="mt-5 text-2xl font-extrabold text-slate-900">{label}</h1>
      <p className="mt-2 max-w-md text-sm text-slate-500">
        This module is part of the Leadflow.io suite. The interface for{' '}
        <span className="font-semibold text-slate-700">{label}</span> is coming soon in this demo build.
      </p>
      <div className="mt-6">
        <PrimaryButton icon={Plus} onClick={() => notify(`${label} — coming soon`)}>
          Get Started
        </PrimaryButton>
      </div>
    </div>
  )
}

/* -------------------------------------------------------------------------- */
/*  Team & Permissions (Admin)                                                */
/* -------------------------------------------------------------------------- */

function PermToggle({ on, onClick, disabled }) {
  return (
    <button onClick={onClick} disabled={disabled} className={`relative h-5 w-9 shrink-0 rounded-full transition disabled:opacity-40 ${on ? 'bg-brand' : 'bg-slate-300'}`}>
      <span className={`absolute top-0.5 h-4 w-4 rounded-full bg-white shadow transition-all ${on ? 'left-[18px]' : 'left-0.5'}`} />
    </button>
  )
}

function TeamPermissionsPage({ myUid, role = 'Member', can = () => true }) {
  const notify = useToast()
  // A Manager can invite/add members, but changing roles or fine-tuning permissions is
  // strictly Owner/Admin (client permissions matrix). This is role-based on purpose — it must
  // NOT be grantable via a per-user "all permissions" override, or a Member could self-manage.
  const canManage = ['Owner', 'Admin'].includes(role)
  const [users, setUsers] = useState({})
  const [openUid, setOpenUid] = useState(null)
  const [loading, setLoading] = useState(true)
  const [err, setErr] = useState(false)
  const [addOpen, setAddOpen] = useState(false)
  const [form, setForm] = useState({ name: '', email: '', password: '', role: 'Member', allPerms: false })
  const [busy, setBusy] = useState(false)

  const submitMember = async () => {
    const { name, email, password } = form
    // Managers can invite, but only as a plain Member with no permission overrides —
    // choosing a higher role or granting all permissions is Owner/Admin only.
    const role = canManage ? form.role : 'Member'
    const allPerms = canManage ? form.allPerms : false
    if (!email.trim() || password.length < 6) { notify('Enter an email and a password of 6+ characters', 'error'); return }
    setBusy(true)
    try {
      const uid = await createMemberAccount({ email: email.trim(), password, name: name.trim() || email.trim().split('@')[0] })
      const overrides = allPerms ? encodeOverrides(Object.fromEntries(PERMISSION_GROUPS.flatMap((g) => g.perms.map((p) => [p.key, true])))) : {}
      await dbSet(dbRef(db, `users/${uid}`), { name: name.trim() || email.trim().split('@')[0], email: email.trim(), role, overrides })
      notify('Member added')
      setAddOpen(false); setForm({ name: '', email: '', password: '', role: 'Member', allPerms: false })
    } catch (e) {
      const msg = e.code === 'auth/email-already-in-use' ? 'That email already has an account' : e.code === 'auth/weak-password' ? 'Password should be at least 6 characters' : 'Could not add member — check the details and DB rules'
      notify(msg, 'error')
    } finally { setBusy(false) }
  }

  // Close the Add Member dialog and clear whatever was typed, so it opens blank next time.
  const closeAddMember = () => { setAddOpen(false); setForm({ name: '', email: '', password: '', role: 'Member', allPerms: false }) }

  useEffect(() => {
    return onValue(dbRef(db, 'users'), (snap) => { setUsers(snap.val() || {}); setLoading(false) }, () => { setErr(true); setLoading(false) })
  }, [])

  const list = Object.entries(users).map(([uid, u]) => ({ uid, ...u })).sort((a, b) => (a.name || '').localeCompare(b.name || ''))

  const setUserRole = (uid, role) => { dbUpdate(dbRef(db, `users/${uid}`), { role }).then(() => notify('Role updated')).catch(() => notify('Save failed — check DB rules', 'error')) }
  const [confirmDelUser, setConfirmDelUser] = useState(null) // user pending removal from the team
  const removeUser = () => {
    const u = confirmDelUser
    dbRemove(dbRef(db, `users/${u.uid}`)).then(() => notify(`Removed ${u.name || u.email}`, 'error')).catch(() => notify('Remove failed — check DB rules', 'error'))
    setConfirmDelUser(null)
  }
  const togglePerm = (uid, key) => {
    const u = users[uid]; if (!u) return
    const overrides = decodeOverrides(u.overrides) // dotted keys
    const eff = resolvePerms(u.role, overrides)
    const preset = new Set(ROLE_PRESETS[u.role] || [])
    const desired = !eff.has(key)
    if (desired === preset.has(key)) delete overrides[key]
    else overrides[key] = desired
    dbSet(dbRef(db, `users/${uid}/overrides`), encodeOverrides(overrides)).catch(() => notify('Save failed — check DB rules', 'error'))
  }

  const roleBadge = (r) => ({ Owner: 'bg-amber-50 text-amber-700', Admin: 'bg-rose-50 text-rose-700', Manager: 'bg-indigo-50 text-indigo-700', Member: 'bg-slate-100 text-slate-600' }[r] || 'bg-slate-100 text-slate-600')

  return (
    <div className="mx-auto max-w-4xl px-6 py-8">
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div className="flex items-start gap-3">
          <div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-blue-50 text-blue-500"><Users className="h-6 w-6" /></div>
          <div>
            <h1 className="text-2xl font-extrabold text-slate-900">Team &amp; Permissions</h1>
            <p className="mt-1 text-sm text-slate-500">{canManage ? "Set each member's role, then fine-tune exactly which functions they can use." : 'Invite new members to your team. Roles and permissions are managed by an Admin or Owner.'}</p>
          </div>
        </div>
        <button onClick={() => setAddOpen(true)} className="inline-flex items-center gap-1.5 rounded-lg bg-brand px-3 py-2 text-sm font-semibold text-white shadow-sm transition hover:bg-brand-hover"><Plus className="h-4 w-4" /> Add Member</button>
      </div>

      {addOpen && (
        <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/50 p-4">
          <div className="w-full max-w-md overflow-hidden rounded-2xl bg-white shadow-2xl">
            <div className="flex items-center justify-between border-b border-slate-200 px-5 py-4">
              <h3 className="text-lg font-extrabold text-slate-900">Add Team Member</h3>
              <button onClick={() => !busy && closeAddMember()} className="rounded-lg p-1.5 text-slate-400 transition hover:bg-slate-100 hover:text-slate-700"><X className="h-5 w-5" /></button>
            </div>
            <div className="space-y-3 p-5">
              <p className="text-xs text-slate-500">Creates a login for the member. Share the email &amp; password with them — they can change the password later.</p>
              <div>
                <label className="mb-1 block text-sm font-semibold text-slate-700">Full Name</label>
                <input value={form.name} onChange={(e) => setForm((f) => ({ ...f, name: e.target.value }))} placeholder="Jane Doe" className={inputCls} />
              </div>
              <div>
                <label className="mb-1 block text-sm font-semibold text-slate-700">Email</label>
                <input type="email" value={form.email} onChange={(e) => setForm((f) => ({ ...f, email: e.target.value }))} placeholder="jane@company.com" className={inputCls} />
              </div>
              <div>
                <label className="mb-1 block text-sm font-semibold text-slate-700">Temporary Password</label>
                <input value={form.password} onChange={(e) => setForm((f) => ({ ...f, password: e.target.value }))} placeholder="At least 6 characters" className={inputCls} />
              </div>
              {canManage ? (
                <>
                  <div>
                    <label className="mb-1 block text-sm font-semibold text-slate-700">Role</label>
                    <select value={form.role} onChange={(e) => setForm((f) => ({ ...f, role: e.target.value }))} className={inputCls}>
                      {ROLES.map((r) => <option key={r}>{r}</option>)}
                    </select>
                  </div>
                  <label className="flex cursor-pointer items-center gap-2 text-sm text-slate-700">
                    <input type="checkbox" checked={form.allPerms} onChange={(e) => setForm((f) => ({ ...f, allPerms: e.target.checked }))} className="h-4 w-4 rounded border-slate-300 text-brand focus:ring-blue-300" />
                    Grant <b>all permissions</b> to this member
                  </label>
                </>
              ) : (
                <p className="rounded-lg bg-slate-50 px-3 py-2 text-xs text-slate-500">New members join as <b>Member</b>. Only an Admin or Owner can change roles &amp; permissions afterward.</p>
              )}
            </div>
            <div className="flex items-center justify-end gap-2 border-t border-slate-200 px-5 py-3">
              <button onClick={closeAddMember} disabled={busy} className="rounded-lg px-4 py-2 text-sm font-semibold text-slate-600 transition hover:text-slate-900">Cancel</button>
              <button onClick={submitMember} disabled={busy} className="rounded-lg bg-brand px-4 py-2 text-sm font-semibold text-white shadow-sm transition hover:bg-brand-hover disabled:opacity-60">{busy ? 'Adding…' : 'Add Member'}</button>
            </div>
          </div>
        </div>
      )}

      <div className="mt-4 rounded-xl border border-blue-100 bg-blue-50/60 p-4 text-sm text-blue-800">
        New members join by choosing <b>Create account</b> on the sign-in page. They start as <b>Member</b> and appear here — then you adjust their access below.
      </div>

      {loading ? (
        <p className="mt-8 text-sm text-slate-400">Loading team…</p>
      ) : err ? (
        <p className="mt-8 rounded-lg bg-amber-50 p-4 text-sm text-amber-700">Couldn't read the team from Firebase. Make sure Realtime Database rules allow authenticated reads of <code>/users</code>.</p>
      ) : (
        <div className="mt-5 space-y-3">
          {list.map((u) => {
            const eff = resolvePerms(u.role, decodeOverrides(u.overrides))
            const isMe = u.uid === myUid
            const open = openUid === u.uid
            return (
              <div key={u.uid} className="overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
                <div className="flex flex-wrap items-center gap-3 p-4">
                  <div className="flex h-10 w-10 items-center justify-center rounded-full bg-slate-100 text-sm font-bold text-slate-500">{(u.name || u.email || '?').slice(0, 1).toUpperCase()}</div>
                  <div className="min-w-0 flex-1">
                    <p className="truncate text-sm font-bold text-slate-900">{u.name || '—'} {isMe && <span className="ml-1 rounded bg-slate-100 px-1.5 py-0.5 text-[10px] font-semibold text-slate-500">You</span>}</p>
                    <p className="truncate text-xs text-slate-500">{u.email}</p>
                  </div>
                  <span className={`rounded-full px-2.5 py-1 text-xs font-semibold ${roleBadge(u.role)}`}>{u.role}</span>
                  <select value={u.role} onChange={(e) => setUserRole(u.uid, e.target.value)} disabled={isMe || !canManage} title={canManage ? '' : 'Only an Admin or Owner can change roles'} className="rounded-lg border border-slate-200 bg-white px-2 py-1.5 text-sm text-slate-700 outline-none disabled:opacity-50">
                    {ROLES.map((r) => <option key={r}>{r}</option>)}
                  </select>
                  <button onClick={() => setOpenUid(open ? null : u.uid)} className="inline-flex items-center gap-1 rounded-lg border border-slate-200 px-3 py-1.5 text-sm font-semibold text-slate-700 transition hover:bg-slate-50">
                    Permissions <ChevronDown className={`h-4 w-4 transition ${open ? 'rotate-180' : ''}`} />
                  </button>
                  {canManage && (isMe ? (
                    <span className="inline-flex h-8 w-8 items-center justify-center text-slate-300" title="You can't remove yourself"><Trash2 className="h-4 w-4" /></span>
                  ) : (
                    <button onClick={() => setConfirmDelUser(u)} title="Remove from team" className="flex h-8 w-8 items-center justify-center rounded-lg border border-slate-200 text-slate-500 transition hover:border-rose-200 hover:bg-rose-50 hover:text-rose-600"><Trash2 className="h-4 w-4" /></button>
                  ))}
                </div>
                {open && (
                  <div className="border-t border-slate-100 bg-slate-50/50 p-4">
                    {isMe && <p className="mb-3 rounded-lg bg-amber-50 px-3 py-2 text-xs text-amber-700">You can't remove your own admin access here.</p>}
                    <div className="grid gap-5 sm:grid-cols-2">
                      {PERMISSION_GROUPS.map((grp) => (
                        <div key={grp.group}>
                          <p className="mb-1.5 text-[11px] font-bold uppercase tracking-wide text-slate-400">{grp.group}</p>
                          <div className="space-y-1.5">
                            {grp.perms.map((p) => {
                              const preset = (ROLE_PRESETS[u.role] || []).includes(p.key)
                              const on = eff.has(p.key)
                              const overridden = on !== preset
                              return (
                                <div key={p.key} className="flex items-center justify-between gap-2 rounded-lg bg-white px-3 py-2 ring-1 ring-slate-100">
                                  <span className="text-sm text-slate-700">{p.label}{overridden && <span className="ml-1.5 rounded bg-orange-50 px-1 py-0.5 text-[9px] font-bold uppercase text-orange-600">custom</span>}</span>
                                  <PermToggle on={on} onClick={() => togglePerm(u.uid, p.key)} disabled={isMe || !canManage} />
                                </div>
                              )
                            })}
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            )
          })}
        </div>
      )}

      {/* Remove-from-team confirm */}
      {confirmDelUser && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 p-4">
          <div className="w-full max-w-sm rounded-2xl bg-white p-6 shadow-xl">
            <div className="flex items-center gap-3"><span className="flex h-10 w-10 items-center justify-center rounded-full bg-rose-50 text-rose-500"><Trash2 className="h-5 w-5" /></span><div><p className="text-base font-bold text-slate-900">Remove from team?</p><p className="text-sm text-slate-500">{confirmDelUser.name || confirmDelUser.email} will lose all access.</p></div></div>
            <div className="mt-5 flex justify-end gap-2"><button onClick={() => setConfirmDelUser(null)} className="rounded-lg border border-slate-200 px-4 py-2 text-sm font-semibold text-slate-700 hover:bg-slate-50">Cancel</button><button onClick={removeUser} className="rounded-lg bg-rose-600 px-4 py-2 text-sm font-bold text-white hover:bg-rose-700">Remove</button></div>
          </div>
        </div>
      )}
    </div>
  )
}

/* -------------------------------------------------------------------------- */
/*  Main App                                                                  */
/* -------------------------------------------------------------------------- */

export default function App() {
  const [isLoggedIn, setIsLoggedIn] = useState(false)
  const [authReady, setAuthReady] = useState(false)
  const [active, setActive] = usePersistentState('active_view', 'crm') // survives page refresh; land on My Leads
  const [user, setUser] = useState(CURRENT_USER)
  const [myUid, setMyUid] = useState(null)
  const [role, setRole] = useState('Member')
  const [perms, setPerms] = useState(() => new Set())
  const can = (key) => perms.has(key)

  // Firebase Auth is the source of truth. On sign-in we ensure a profile exists
  // in the Realtime DB (the FIRST account to sign up becomes the Admin), then
  // resolve that user's effective permissions from their role + overrides.
  useEffect(() => {
    return onAuthStateChanged(auth, async (u) => {
      if (u) {
        // Point all saved data at THIS user's namespace before the app renders — each account
        // has its own separate data (a new user starts empty and builds their own).
        setDataNamespace(u.uid); setApiNamespace(u.uid)
        try { localStorage.setItem('crebuilder_owner_uid', u.uid) } catch { /* ignore */ }
        const name = u.displayName || (u.email ? u.email.split('@')[0] : CURRENT_USER.name)
        setUser({ ...CURRENT_USER, name, email: u.email || '', initials: name.slice(0, 1).toUpperCase() })
        setMyUid(u.uid)
        setIsLoggedIn(true)
        let profile = null
        try {
          const usersSnap = await dbGet(dbRef(db, 'users'))
          const users = usersSnap.val() || {}
          profile = users[u.uid]
          if (!profile) {
            const isFirst = Object.keys(users).length === 0
            profile = { name, email: u.email || '', role: isFirst ? 'Owner' : 'Member', overrides: {}, createdAt: u.metadata?.creationTime || '' }
            await dbSet(dbRef(db, `users/${u.uid}`), profile)
          }
        } catch {
          // DB unreachable / rules blocking — fall back to Member (no elevated access).
          profile = { role: 'Member', overrides: {} }
        }
        setRole(profile.role || 'Member')
        setPerms(resolvePerms(profile.role || 'Member', decodeOverrides(profile.overrides)))
        // Store the user + role in the backend so the API can enforce permissions server-side.
        saveUser({ name, email: u.email, role: profile.role || 'Member' }).catch(() => {})
      } else {
        setDataNamespace(''); setApiNamespace('')
        setIsLoggedIn(false)
        setRole('Member')
        setPerms(new Set())
        setMyUid(null)
      }
      setAuthReady(true)
    })
  }, [])
  const [query, setQuery] = useState('')

  // Live app data — shared across screens
  const [packages, setPackages] = useState(INITIAL_PACKAGES)
  const [listings, setListings] = useState(INITIAL_LISTINGS)
  const [deals, setDeals] = useState(INITIAL_DEALS)
  const [dealRooms, setDealRooms] = useState(INITIAL_DEAL_ROOMS)

  // Load from MongoDB on startup (falls back to seed data if the backend is offline),
  // then persist any change back to the database.
  const [dbLoaded, setDbLoaded] = useState(false)
  const [mobileNav, setMobileNav] = useState(false)
  const [createNonce, setCreateNonce] = useState(0)
  const [resume, setResume] = useState(null) // { draft, nonce } — resume a builder draft
  useEffect(() => {
    let alive = true
    // A different user just signed in (or signed out): clear the previous account's
    // in-memory data immediately, then load THIS user's own data. The App root never
    // remounts, so without this the last account's data would linger and get re-saved
    // under the new account's namespace.
    setDbLoaded(false)
    setPackages(INITIAL_PACKAGES)
    setListings(INITIAL_LISTINGS)
    setDeals(INITIAL_DEALS)
    setDealRooms(INITIAL_DEAL_ROOMS)
    ;(async () => {
      try {
        const [p, l, d] = await Promise.all([getCol('packages'), getCol('listings'), getCol('dealrooms')])
        if (!alive) return
        if (p && p.length) setPackages(p)
        else await putCol('packages', INITIAL_PACKAGES)
        if (l && l.length) setListings(l)
        else await putCol('listings', INITIAL_LISTINGS)
        if (d && d.length) setDealRooms(d)
        else await putCol('dealrooms', INITIAL_DEAL_ROOMS)
      } catch {
        /* backend not running — keep in-memory seed data */
      }
      if (alive) setDbLoaded(true)
    })()
    return () => {
      alive = false
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [myUid])
  useEffect(() => {
    if (dbLoaded) putCol('packages', packages).catch(() => {})
  }, [packages, dbLoaded])
  useEffect(() => {
    if (dbLoaded) putCol('listings', listings).catch(() => {})
  }, [listings, dbLoaded])
  useEffect(() => {
    if (dbLoaded) putCol('dealrooms', dealRooms).catch(() => {})
  }, [dealRooms, dbLoaded])

  // Backfill a Deal ID (##-######) onto any older deal that predates the Deal ID system.
  // Step 1: every LISTING gets an ID (the listing is the source of truth for a deal's ID).
  useEffect(() => {
    if (!dbLoaded) return
    setListings((list) => (list.some((l) => !l.dealId) ? list.map((l) => (l.dealId ? l : { ...l, dealId: newDealId() })) : list))
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [dbLoaded])
  // Step 2: once listings have IDs, sync each package + deal room to its matching listing's ID
  // (match by shared id, or by name/address) so My Deals and the deal room show the SAME ID.
  useEffect(() => {
    if (!dbLoaded) return
    const norm = (s) => (s || '').trim().toLowerCase()
    const findListing = (o) =>
      listings.find((l) => (o.id && l.id === o.id)) ||
      listings.find((l) => (o.listingId && l.id === o.listingId)) ||
      listings.find((l) => (o.name && norm(l.name) === norm(o.name)) || (o.address && norm(l.address) === norm(o.address)))
    setPackages((list) => {
      let changed = false
      const next = list.map((p) => {
        const m = findListing(p)
        const want = (m && m.dealId) || p.dealId || newDealId()
        if (p.dealId !== want) { changed = true; return { ...p, dealId: want } }
        return p
      })
      return changed ? next : list
    })
    setDealRooms((list) => {
      let changed = false
      const next = list.map((r) => {
        const m = findListing(r)
        const want = (m && m.dealId) || r.dealId || newDealId()
        if (r.dealId !== want) { changed = true; return { ...r, dealId: want } }
        return r
      })
      return changed ? next : list
    })
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [dbLoaded, listings])

  // onAuthStateChanged already sets the user + logged-in flag; just reset the view.
  const handleLogin = () => { setActive('crm') }

  const handleSignOut = () => {
    setQuery('')
    signOut(auth).catch(() => {})
  }

  const navigate = (key) => {
    setActive(key)
    setQuery('')
    setMobileNav(false)
  }

  // Document creation removed per spec — every "create/new" path now goes to My Deals, where
  // the crexi-style New Deal wizard captures details as input fields (no document builder).
  const startCreate = () => {
    setActive('listings')
    setMobileNav(false)
  }
  const resumeDraft = () => {
    setActive('listings')
    setMobileNav(false)
  }

  // Clicking a property on the Dashboard opens that property's Deal Room —
  // matching an existing room by address/name, or creating one on the fly.
  const [dealRoomTarget, setDealRoomTarget] = useState(null)
  const openDealRoomFor = (pkg) => {
    if (!pkg) return
    const addr = (pkg.address || '').trim().toLowerCase()
    const name = (pkg.title || pkg.name || '').trim().toLowerCase()
    // Prefer the room linked to THIS exact listing (by id) so two deals that share an address or
    // name never resolve to — and get re-linked to — the same room (which cross-links their OMs).
    let room = dealRooms.find((r) => r.listingId && r.listingId === pkg.id) || dealRooms.find(
      (r) =>
        (addr && (r.address || '').trim().toLowerCase() === addr) ||
        (name && (r.name || '').trim().toLowerCase() === name),
    )
    if (!room) {
      room = {
        id: uid(),
        listingId: pkg.id, // link this deal room to the listing so its OM feeds Download Package
        dealId: pkg.dealId || newDealId(), // the room shares the listing's Deal ID
        name: pkg.title || pkg.name || 'Untitled Property',
        address: pkg.address || '',
        price: pkg.price || 0, // carry the listing's price so it shows under the title
        capRate: pkg.capRate || '',
        noi: pkg.noi || '',
        image: pkg.image || '',
        status: 'Active',
        access: 'Free Access',
        files: 0,
        members: 0,
        updated: 'just now',
        ts: Date.now(),
      }
      setDealRooms((list) => [room, ...list])
    } else if (room.listingId !== pkg.id || (pkg.dealId && room.dealId !== pkg.dealId)) {
      // Keep the room linked to the listing AND sharing its Deal ID (fixes older rooms whose
      // ID was backfilled separately from the listing).
      room = { ...room, listingId: pkg.id, dealId: pkg.dealId || room.dealId }
      setDealRooms((list) => list.map((r) => (r.id === room.id ? { ...r, listingId: pkg.id, dealId: pkg.dealId || r.dealId } : r)))
    }
    setDealRoomTarget(room)
    setActive('deals')
    setMobileNav(false)
  }

  if (!authReady) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-slate-50 text-slate-400">
        <div className="flex items-center gap-2 text-sm font-medium">
          <div className="h-5 w-5 animate-spin rounded-full border-2 border-slate-200 border-t-brand" /> Loading…
        </div>
      </div>
    )
  }

  if (!isLoggedIn) {
    return (
      <ToastProvider>
        <LoginPage onLogin={handleLogin} />
      </ToastProvider>
    )
  }

  const activeLabel = NAV_ITEMS.find((n) => n.key === active)?.label || 'My Leads'

  const renderScreen = () => {
    switch (active) {
      case 'dashboard':
        return <DashboardPage packages={packages} setPackages={setPackages} setListings={setListings} globalQuery={query} createNonce={createNonce} resume={resume} onResumeHandled={() => setResume(null)} onNavigate={navigate} onSignOut={handleSignOut} onOpenDealRoom={openDealRoomFor} dealRooms={dealRooms} setDealRooms={setDealRooms} onOpenRoom={(room) => { setDealRoomTarget(room); setActive('deals'); setMobileNav(false) }} onDeleteRoom={(room) => { if (window.confirm(`Delete deal room "${room.name}"?`)) setDealRooms((list) => list.filter((r) => r.id !== room.id)) }} onUpdateRoom={(id, data) => setDealRooms((list) => list.map((r) => (r.id === id ? { ...r, ...data, ts: Date.now(), updated: 'just now' } : r)))} onTransferRoom={(id, name) => setDealRooms((list) => list.map((r) => (r.id === id ? { ...r, assignee: name, owner_name: name } : r)))} onDuplicateRoom={(room) => setDealRooms((list) => [{ ...room, id: uid(), name: `${room.name} (Copy)`, ts: Date.now(), updated: 'just now' }, ...list])} user={user} can={can} />
      case 'listings':
        return <ListingHubPage listings={listings} setListings={setListings} setPackages={setPackages} globalQuery={query} onCreateNew={startCreate} onResumeDraft={resumeDraft} onOpenDealRoom={openDealRoomFor} dealRooms={dealRooms} setDealRooms={setDealRooms} onOpenRoom={(room) => { setDealRoomTarget(room); setActive('deals'); setMobileNav(false) }} user={user} role={role} can={can} />
      case 'deals':
        return <DealRoomsPage dealRooms={dealRooms} setDealRooms={setDealRooms} listings={listings} setListings={setListings} onEditDocument={resumeDraft} openTarget={dealRoomTarget} onOpenHandled={() => setDealRoomTarget(null)} onExit={() => { setDealRoomTarget(null); navigate('listings') }} user={user} role={role} />
      case 'team':
        // Role-based (not override-based): Owner/Admin/Manager may open this page. A Manager can
        // only add members; changing roles/permissions is locked to Owner/Admin inside the page.
        return ['Owner', 'Admin', 'Manager'].includes(role) ? <TeamPermissionsPage myUid={myUid} role={role} can={can} /> : <NoAccessPage />
      case 'profile':
        return <ProfileSettingsPage user={user} />
      case 'teamsettings':
        return ['Owner', 'Admin'].includes(role) ? <TeamSettingsPage role={role} /> : <NoAccessPage />
      case 'documents':
        return <PlaceholderPage label="Documents" icon={FileText} />
      case 'crm':
        return <CRMPage user={user} onNavigate={navigate} role={role} can={can} />
      case 'email':
        return <EmailBlastPage user={user} onNavigate={navigate} role={role} />
      case 'templates':
        return <PlaceholderPage label="Custom Templates" icon={Wand2} />
      case 'knowledge':
        return <PlaceholderPage label="Knowledge Base" icon={BookOpen} />
      default:
        return <DashboardPage packages={packages} setPackages={setPackages} setListings={setListings} globalQuery={query} createNonce={createNonce} resume={resume} onResumeHandled={() => setResume(null)} onNavigate={navigate} onSignOut={handleSignOut} onOpenDealRoom={openDealRoomFor} dealRooms={dealRooms} setDealRooms={setDealRooms} onOpenRoom={(room) => { setDealRoomTarget(room); setActive('deals'); setMobileNav(false) }} onDeleteRoom={(room) => { if (window.confirm(`Delete deal room "${room.name}"?`)) setDealRooms((list) => list.filter((r) => r.id !== room.id)) }} onUpdateRoom={(id, data) => setDealRooms((list) => list.map((r) => (r.id === id ? { ...r, ...data, ts: Date.now(), updated: 'just now' } : r)))} onTransferRoom={(id, name) => setDealRooms((list) => list.map((r) => (r.id === id ? { ...r, assignee: name, owner_name: name } : r)))} onDuplicateRoom={(room) => setDealRooms((list) => [{ ...room, id: uid(), name: `${room.name} (Copy)`, ts: Date.now(), updated: 'just now' }, ...list])} user={user} can={can} />
    }
  }

  return (
    <ToastProvider>
      <div className="flex h-screen overflow-hidden bg-slate-50 text-slate-900">
        {/* Desktop sidebar */}
        <div className="hidden md:block">
          <Sidebar active={active} onNavigate={navigate} onSignOut={handleSignOut} user={user} can={can} role={role} responsiveCollapse />
        </div>

        {/* Mobile slide-in drawer */}
        {mobileNav && (
          <div className="fixed inset-0 z-50 md:hidden">
            <div
              className="absolute inset-0 bg-slate-900/50 backdrop-blur-sm"
              style={{ animation: 'drawer-fade 0.25s ease-out' }}
              onClick={() => setMobileNav(false)}
            />
            <div className="absolute left-0 top-0 h-full shadow-2xl" style={{ animation: 'drawer-in 0.3s ease-out' }}>
              <Sidebar
                active={active}
                onNavigate={(k) => { setMobileNav(false); navigate(k) }}
                onClose={() => setMobileNav(false)}
                onSignOut={() => {
                  setMobileNav(false)
                  handleSignOut()
                }}
                user={user}
                can={can}
                role={role}
              />
            </div>
          </div>
        )}

        <div className="flex min-h-0 min-w-0 flex-1 flex-col">
          {/* Mobile-only sticky header: menu · logo · create */}
          <header className="sticky top-0 z-40 flex shrink-0 items-center justify-between border-b border-slate-200 bg-white px-3 py-2 md:hidden">
            <button
              onClick={() => setMobileNav(true)}
              className="inline-flex h-10 w-10 items-center justify-center rounded-lg text-slate-600 transition hover:bg-slate-100"
              aria-label="Open menu"
            >
              <Menu className="h-6 w-6" />
            </button>
            <div className="flex h-9 w-9 items-center justify-center rounded-xl bg-gradient-to-br from-orange-400 to-orange-600 text-white shadow-sm">
              <Box className="h-5 w-5" />
            </div>
            {can('document.create') ? (
              <button
                onClick={startCreate}
                className="inline-flex h-10 w-10 items-center justify-center rounded-xl bg-emerald-500 text-white shadow-sm transition hover:bg-emerald-600"
                aria-label="Create new"
              >
                <Plus className="h-6 w-6" />
              </button>
            ) : (
              <span className="h-10 w-10" />
            )}
          </header>
          <main className="scrollbar-slim relative min-h-0 flex-1 overflow-y-auto">{renderScreen()}</main>
        </div>
      </div>
    </ToastProvider>
  )
}
